                    p.id = item->info->effect;
                    p.a = item->pos;
                    p.b = params.quat;
                    p.c.z = 0.0f;
                    p.c.y = 0.0f;
                    p.c.x = 0.0f;
                    p.player = 0;
                    p.f0 = 0.0f;
                    p.f1 = 0.0f;
                    p.zero = g_zeroVector;
                    ThingManager_DARYL_CreateThing(1, &p);
