void AI_Car_Heartbeat(u8 *ai) {
    typedef struct AICarTarget {
        u32 timer;
        u8 unk4[8];
        f32 unkC;
        f32 unk10;
    } AICarTarget;
    typedef struct AICarTargets {
        u8 unk0[0x4B0];
        AICarTarget targets[16];
    } AICarTargets;
    extern u32 g_iDeltaTimeMS;
    void Control_ClearControl(void *control);
    s8 AI_Heartbeat(u8 *ai);
    void AI_Car_Reset(u8 *car);
    s32 AI_Car_DetermineState(u8 *car);
    u32 AI_UpdateTimer(u32 *timer);
    void AI_AddEvent(void *arg0);
    f32 PSVECSquareDistance(void *a, void *b);
    s8 AI_Car_CheckIfStuck(u8 *ai);
    s8 cleared;
    u8 *pos;
    u8 *point;
    u8 *car;
    u16 i;
    s16 j;
    s8 done;

    car = *(u8 **)(ai + 0x2C);
    if (car != NULL && *(u8 **)(car + 0x8C) != g_carAVTable) {
        return;
    }
    Control_ClearControl(ai);
    if (!AI_Heartbeat(ai)) {
        return;
    }
    if (*(s8 *)(ai + 0xCC) && car != NULL) {
        AI_Car_Reset(ai);
    }
    if (*(s8 *)(ai + 0xCC)) {
        return;
    }
    if (*(u32 *)(ai + 0xD0) != 0) {
        AI_Car_DetermineState(ai);
        if (*(u32 *)(ai + 0x3E4) == 0 || (*(u32 *)(ai + 0x3EC) == 0 && *(u32 *)(ai + 0x3F0) == 0)) {
            ai[0x13] = 0xFF;
            if ((*(u8 **)(car + 0x3BC))[0x11] == 1) {
                ai[0x12] = 0xFF;
            }
            return;
        }
        if (*(u32 *)(ai + 0x608) != 0 && AI_UpdateTimer((u32 *)(ai + 0x608)) == 0) {
            AI_AddEvent(ai + 0x5F8);
        }
        if (*(u32 *)(ai + 0x4AC) != 0) {
            AI_UpdateTimer((u32 *)(ai + 0x4AC));
        }
        if (*(u32 *)(ai + 0x4A4) < 32 && ((u8 **)(ai + 0x420))[*(u32 *)(ai + 0x4A4)] != NULL) {
            pos = *(u8 **)(ai + 0x2C);
            cleared = 1;
            while (cleared && *(u32 *)(ai + 0x4A4) < 32 && (point = *(u8 **)(ai + 0x420 + *(u32 *)(ai + 0x4A4) * 4)) != NULL) {
                cleared = 0;
                if (PSVECSquareDistance(point, pos + 0x40) < *(f32 *)(point + 0x24) * *(f32 *)(point + 0x24)) {
                    AI_Car_ClearedNavPoint(ai, 0);
                    cleared = 1;
                }
            }
        }
        for (i = 0; i < 16 && ((AICarTargets *)ai)->targets[i].timer != 0; i++) {
            done = 0;
            while (!done) {
                done = 1;
                if (((AICarTargets *)ai)->targets[i].timer != 0) {
                    ((AICarTargets *)ai)->targets[i].unkC += g_iDeltaTimeMS;
                    ((AICarTargets *)ai)->targets[i].unk10 += g_iDeltaTimeMS;
                    if (((AICarTargets *)ai)->targets[i].unkC > 500.0f && ((AICarTargets *)ai)->targets[i].unk10 > 500.0f) {
                        for (j = i; j < 16 && ((AICarTargets *)ai)->targets[j].timer != 0; j++) {
                            if (j == 15) {
                                ((AICarTargets *)ai)->targets[j].timer = 0;
                            } else {
                                ((AICarTargets *)ai)->targets[j] = ((AICarTargets *)ai)->targets[j + 1];
                            }
                        }
                        done = 0;
                    }
                }
            }
        }
        *(u32 *)(ai + 0x5F0) = 0;
        *(u32 *)(ai + 0x5F4) = 0;
        if (*(u32 *)(ai + 0x5F0) != 0) {
            *(u32 *)(ai + 0x5F4) += g_iDeltaTimeMS;
            if (*(u32 *)(ai + 0x5F4) > 20000) {
                *(u32 *)(ai + 0x5F4) = 0;
                *(u32 *)(ai + 0x5F0) = 0;
            }
        }
        if (!AI_Car_CheckIfStuck(ai)) {
            AI_Car_SeekPoint(ai);
        }
        AI_UpdateTimer((u32 *)(ai + 0x658));
        if (*(u32 *)(ai + 0x654) != 0 && AI_UpdateTimer((u32 *)(ai + 0x654)) == 0) {
            AI_AddEvent(ai + 0x644);
        }
    }
}

void MotionState_Init(void *arg0, s8 reset) {
    typedef struct {
        u8 pad0[0x14];
        u32 *skel;
        u8 pad18[4];
        u8 loop[3];
        u8 pad1F;
        f32 *time[3];
    } Anim;
    typedef struct {
        Anim *anim;
        u8 mode;
        u8 unk5;
        u8 unk6;
        u8 unk7;
        u8 pad8[4];
        f32 time;
    } MotionState;
    typedef struct {
        Anim *anim;
        u8 mode;
        u8 unk5;
        u8 unk6;
        u8 pad7;
        f32 time;
        f32 blend;
        u8 pad10[0x10];
    } MotionHistory;
    typedef struct {
        MotionState cur;
        u32 matrices;
        u8 pad14[4];
        MotionHistory hist[1];
    } Motion;
    void MotionState_ReleaseSlavesByType(s32 state, u8 type);
    u32 MatrixCache_Get(u32 size, void *mtx);
    Motion *motion = arg0;
    s32 i;
    u32 *skel;

    motion->cur.unk5 = 0;
    motion->cur.unk6 = 0;
    motion->cur.mode = 0;
    motion->cur.mode = 0;
    if (motion->cur.anim == NULL) {
        return;
    }
    if (!motion->cur.anim->loop[0]) {
        motion->cur.mode++;
        if (!motion->cur.anim->loop[1]) {
            motion->cur.mode++;
            if (motion->cur.anim->loop[2]) {
                motion->cur.time = *motion->cur.anim->time[2];
            }
        } else {
            motion->cur.time = *motion->cur.anim->time[1];
        }
    } else {
        motion->cur.time = *motion->cur.anim->time[0];
    }
    for (;;) {
        switch (motion->cur.mode) {
        case 0:
            if (motion->cur.anim->loop[0]) {
                goto done;
            }
            motion->cur.mode = 1;
        case 1:
            if (motion->cur.anim->loop[1]) {
                goto done;
            }
            motion->cur.mode = 2;
        case 2:
            if (motion->cur.anim->loop[2]) {
                goto done;
            }
            motion->cur.mode = 0;
        }
    }
done:
    if (reset) {
        for (i = 0; i > 0; i--) {
            memcpy(&motion->hist[i], &motion->hist[i - 1], sizeof(MotionHistory));
        }
        motion->hist[0].blend = 0.0f;
    } else {
        motion->hist[0].blend = 1.0f;
    }
    motion->hist[0].anim = motion->cur.anim;
    motion->hist[0].mode = motion->cur.mode;
    motion->hist[0].unk5 = motion->cur.unk5;
    motion->hist[0].unk6 = motion->cur.unk6;
    motion->hist[0].time = motion->cur.time;
    skel = motion->cur.anim->skel;
    if (motion->cur.unk7 < *skel) {
        if (motion->cur.unk7) {
            MatrixCache_Free(motion->matrices);
        }
        motion->matrices = MatrixCache_Get(*skel, motion);
        motion->cur.unk7 = *skel;
    }
    MotionState_ReleaseSlavesByType((s32)motion, 0xFF);
}

