#pragma inline_depth(6)
s32 AnimNodes_BlowBranch(u8 *node) {
    s32 count = 1;
    u32 i;
    u8 *child = node + 0x20;

    if (node[0x1F] & 3) {
        return 0;
    }
    node[0x1F] |= 2;
    for (i = 0; i < node[0x1C]; i++) {
        count += AnimNodes_BlowBranch(child);
        child += child[0x1E] << 5;
    }
    return count;
}
