static inline void CarA_FitCubic(f32 *coef, f32 x0, f32 x1, f32 y0, f32 y1, f32 m0, f32 m1) {
    f32 dx = x0 - x1;
    f32 dy = y0 - y1;
    f32 a;
    f32 b;
    f32 c;

    a = ((m0 + m1) - 2.0f * dy / dx) / (dx * dx);
    coef[0] = a;
    b = (m0 - dy / dx) / dx - a * (x0 + x1);
    coef[1] = b;
    c = m0 - 3.0f * a * x0 * x0 - 2.0f * b * x0;
    coef[2] = c;
    coef[3] = y0 - a * x0 * x0 * x0 - b * x0 * x0 - c * x0;
}

