    void Trail_AddSegment(u32 *handle, f32 *pos, f32 *dir, u16 texture, u8 *color, s32 life, f32 width0, f32 width1);
    f32 Sqrt(f32 x);
    extern Matrix4 g_identity;
    extern void *g_pSourcePlayer;
    u32 color;
