void Drone_ComputeSuspensionForces(u8 *drone) {
    extern Vector4 g_zeroVector;
    extern u32 g_iLastDeltaTimeMS;
    typedef struct {
        Vector4 pos;
        Vector4 normal;
        u8 pad20[8];
        u8 *material;
        u8 pad2C[4];
        Vector4 unk30;
        u8 pad40[0x10];
    } WheelHit;
    s8 RayHitsTerrain_Aux3(void *, void *, void *, void *);
    void XformVec(void *mtx, Vector4 *in, Vector4 *out);
    f32 PSVECDotProduct(void *a, void *b);
    void PSVECSubtract(void *a, void *b, void *out);
    void PSVECCrossProduct(void *a, void *b, void *out);
    void PSVECAdd(void *a, void *b, void *out);
    f32 PSVECSquareMag(void *v);
    void PSVECNormalize(void *v, void *out);
    void ProjectVectorToNormal(void *n, void *v);
    f32 MagnitudeVector(void *v);
    void PhysicalObject_ProcessForce(u8 *obj, Vector4 *pos, Vector4 *force, f32 scale);
    f32 _fabs(f32 x);
    WheelHit hit;
    Vector4 dir;
    Vector4 point;
    Vector4 start;
    Vector4 slip;
    Vector4 vel;
    Vector4 spin;
    Vector4 r;
    Vector4 friction;
    Vector4 side;
    f32 t;
    u32 i;
    s8 hitTerrain;
    f32 compression;
    f32 len;
    f32 spring;
    f32 damper;
    f32 mag;
    f32 grip;
    f32 scale;
    f32 gravity;
    f32 turn;
    f32 thrust;
    s8 *input;

    *(u32 *)(drone + 0x150) = 0;
    for (i = 0; i < 4; i++) {
        dir.x = -((Vector4 *)(drone + 0x20))->x;
        dir.y = -((Vector4 *)(drone + 0x20))->y;
        dir.z = -((Vector4 *)(drone + 0x20))->z;
        hit.unk30 = g_zeroVector;
        XformVec(drone + 0x10, (Vector4 *)(drone + i * 0x10 + 0x190), &start);
        start.x += 2.0f * ((Vector4 *)(drone + 0x20))->x;
        start.y += 2.0f * ((Vector4 *)(drone + 0x20))->y;
        start.z += 2.0f * ((Vector4 *)(drone + 0x20))->z;
        t = 5.0f;
        hitTerrain = RayHitsTerrain_Aux3(&start, &dir, &t, &hit);
        compression = 4.0f - t;
        if (hitTerrain) {
            (*(u32 *)(drone + 0x150))++;
            len = 1.0f + compression;
            spring = 700.0f * len;
            damper = 100.0f * ((compression - *(f32 *)(drone + i * 4 + 0x140)) / ((f32)g_iLastDeltaTimeMS / 1000.0f));
            point.x = dir.x * len + start.x;
            point.y = dir.y * len + start.y;
            point.z = dir.z * len + start.z;
            PhysicalObject_ProcessForce(drone, &point, (Vector4 *)(drone + 0x20), (spring + damper) * PSVECDotProduct(drone + 0x20, &hit.normal));
            if (drone[0x1DC] == 0) {
                PSVECSubtract(&point, drone + 0x40, &r);
                PSVECCrossProduct(drone + 0x130, &r, &spin);
                PSVECAdd(drone, &spin, &vel);
                slip.x = vel.x - ((Vector4 *)(drone + 0x30))->x * *(f32 *)(drone + 0x180);
                slip.y = vel.y - ((Vector4 *)(drone + 0x30))->y * *(f32 *)(drone + 0x180);
                slip.z = vel.z - ((Vector4 *)(drone + 0x30))->z * *(f32 *)(drone + 0x180);
                ProjectVectorToNormal(&hit.normal, &slip);
                mag = MagnitudeVector(&slip);
                if (mag > 0.0f) {
                    PSVECDotProduct(drone + 0x20, &hit.normal);
                    spring = 2.1f * spring;
                    PSVECCrossProduct(drone + 0x30, &hit.normal, &side);
                    if (PSVECSquareMag(&side)) {
                        PSVECNormalize(&side, &side);
                    }
                    grip = PSVECDotProduct(&side, drone + 0x20);
                    grip = 1.1f * (1.0f - 1.8f * grip);
                    if (grip < 0.1f) {
                        grip = 0.1f;
                    } else if (grip > 1.0f) {
                        grip = 1.0f;
                    }
                    scale = grip * (*(f32 *)(hit.material + 0x14) * spring) / mag;
                    friction.x = -slip.x * scale;
                    friction.y = -slip.y * scale;
                    friction.z = -slip.z * scale;
                    PhysicalObject_ProcessForce(drone, &point, &friction, 1.0f);
                }
            }
        }
        *(f32 *)(drone + i * 4 + 0x140) = compression;
    }
    gravity = -*(f32 *)(*(u8 **)(*(u8 **)(drone + 0xC0) + 0x10) + 0x2C);
    ((Vector4 *)(drone + 0x100))->x += gravity * ((Vector4 *)(drone + 0x130))->x;
    ((Vector4 *)(drone + 0x100))->y += gravity * ((Vector4 *)(drone + 0x130))->y;
    ((Vector4 *)(drone + 0x100))->z += gravity * ((Vector4 *)(drone + 0x130))->z;
    if (*(u32 *)(drone + 0x150) == 4) {
        if (drone[0x1DC] == 1) {
            ProjectVectorToNormal(drone + 0x10, drone);
            *(f32 *)(drone + 0x180) = PSVECDotProduct(drone, drone + 0x30);
            input = *(s8 **)(drone + 0x94);
            if (input != NULL) {
                thrust = 12.1f * (f32)input[1];
                turn = 10.0f * (f32)-input[0];
                ProjectVectorToNormal(drone + 0x20, drone + 0x110);
                ((Vector4 *)(drone + 0x110))->x += turn * ((Vector4 *)(drone + 0x20))->x;
                ((Vector4 *)(drone + 0x110))->y += turn * ((Vector4 *)(drone + 0x20))->y;
                ((Vector4 *)(drone + 0x110))->z += turn * ((Vector4 *)(drone + 0x20))->z;
                if (_fabs(*(f32 *)(drone + 0x180)) < 100.0f) {
                    ((Vector4 *)(drone + 0xF0))->x += ((Vector4 *)(drone + 0x30))->x * thrust;
                    ((Vector4 *)(drone + 0xF0))->y += ((Vector4 *)(drone + 0x30))->y * thrust;
                    ((Vector4 *)(drone + 0xF0))->z += ((Vector4 *)(drone + 0x30))->z * thrust;
                }
            }
        } else if (_fabs(PSVECDotProduct(drone + 0x10, drone)) < 2.0f) {
            if (_fabs(PSVECDotProduct(drone + 0x20, drone + 0x130)) < 5.0f) {
                drone[0x1DC] = 1;
            }
        }
    } else if (*(u32 *)(drone + 0x150) == 0) {
        drone[0x1DC] = 0;
    }
}

s32 Drone_PreMove(u8 *drone) {
    extern Vector4 g_zeroVector;
    extern f32 g_fDeltaTimeSec;
    void Gfx_AnimExtractKeyFrame(void *anim, f32 time, void *keyFrame, u32 count);
    void QuaternionToSubMatrix(void *quat, void *mtx);
    void TransposeSubMatrix(Matrix4 *mtx);
    void MultiplySubMatrix(void *a, Matrix4 *b, Matrix4 *out);
    void GenerateSpinAngleFromQuaternion(Vector4 *quat, void *axis, f32 *angle);
    void Drone_ComputeSuspensionForces(u8 *drone);
    void PhysicalObject_IntegrateNonLateral(u8 *obj);
    typedef struct {
        Quaternion rot;
        f32 pos[4];
    } KeyFrame;
    Matrix4 inv;
    Matrix4 rel;
    Matrix4 world;
    Matrix4 rot;
    KeyFrame key;
    Quaternion delta;
    Quaternion quat;
    Quaternion tmp;
    f32 angle;

    if (drone[0x1DC] == 2) {
        Gfx_AnimExtractKeyFrame(*(void **)(drone + 0xD4), *(f32 *)(drone + 0x1E4), &key, 1);
        ((Vector4 *)drone)->x = (key.pos[0] - ((Thing *)drone)->mtx.m[3][0]) / g_fDeltaTimeSec;
        ((Vector4 *)drone)->y = (key.pos[1] - ((Thing *)drone)->mtx.m[3][1]) / g_fDeltaTimeSec;
        ((Vector4 *)drone)->z = (key.pos[2] - ((Thing *)drone)->mtx.m[3][2]) / g_fDeltaTimeSec;
        quat = key.rot;
        tmp = key.rot;
        inv = ((Thing *)drone)->mtx;
        Mover_SetRotation(drone, tmp);
        QuaternionToSubMatrix(&quat, &rot);
        TransposeSubMatrix(&inv);
        MultiplySubMatrix(&inv, &rot, &rel);
        MultiplySubMatrix(drone + 0x10, &rel, &world);
        SubMatrixToQuaternion(&rel, (Vector4 *)&delta);
        GenerateSpinAngleFromQuaternion((Vector4 *)&delta, drone + 0x130, &angle);
        angle /= g_fDeltaTimeSec;
        *(f32 *)(drone + 0x130) *= angle;
        *(f32 *)(drone + 0x134) *= angle;
        *(f32 *)(drone + 0x138) *= angle;
        *(u32 *)(drone + 0x74) &= ~0x10;
        *(f32 *)(drone + 0x1E4) += g_fDeltaTimeSec;
        if (*(f32 *)(drone + 0x1E4) > *(f32 *)(*(u8 **)(drone + 0xD4) + 0xC)) {
            *(f32 *)(drone + 0x1E4) = *(f32 *)(*(u8 **)(drone + 0xD4) + 0x8);
        }
    } else {
        *(Vector4 *)(drone + 0x100) = g_zeroVector;
        *(Vector4 *)(drone + 0xF0) = *(Vector4 *)(drone + 0x100);
        ((Vector4 *)(drone + 0xF0))->y += *(f32 *)(*(u8 **)(*(u8 **)(drone + 0xC0) + 0x10) + 0x24) *
                                          *(f32 *)(*(u8 **)(*(u8 **)(drone + 0xC0) + 0x10) + 0x20);
        Drone_ComputeSuspensionForces(drone);
        PhysicalObject_IntegrateNonLateral(drone);
    }
    return 1;
}

void Drone_DynamicCollideImpact(u8 *drone, u8 *collision, f32 force) {
    void PSVECSubtract(Vector4 *a, Vector4 *b, Vector4 *out);
    void PSVECCrossProduct(Vector4 *a, Vector4 *b, Vector4 *out);
    void XformVecOrientation(void *mtx, Vector4 *in, Vector4 *out);
    void InverseXformVecOrientation(void *mtx, Vector4 *in, Vector4 *out);
    void Thing_ProcessEndEvent(u8 *thing, u8 *event, u8 *collision, Vector4 *vel);
    Quaternion normal;
    Quaternion pos;
    Vector4 f;
    Vector4 torque;
    Vector4 r;
    Vector4 scaled;
    Vector4 local;
    f32 scale;

    normal = *(Quaternion *)(collision + 0x10);
    pos = *(Quaternion *)collision;
    if (drone[0x1DC] != 2) {
        scale = force / *(f32 *)(*(u8 **)(*(u8 **)(drone + 0xC0) + 0x10) + 0x20);
        ((Vector4 *)drone)->x += normal.x * scale;
        ((Vector4 *)drone)->y += normal.y * scale;
        ((Vector4 *)drone)->z += normal.z * scale;
        PSVECSubtract((Vector4 *)&pos, (Vector4 *)(drone + 0x40), &r);
        f.x = force * normal.x;
        f.y = force * normal.y;
        f.z = force * normal.z;
        PSVECCrossProduct(&r, &f, &torque);
        ((Vector4 *)(drone + 0x110))->x += torque.x;
        ((Vector4 *)(drone + 0x110))->y += torque.y;
        ((Vector4 *)(drone + 0x110))->z += torque.z;
        InverseXformVecOrientation(drone + 0x10, (Vector4 *)(drone + 0x110), &local);
        scaled.x = ((Vector4 *)(drone + 0x120))->x * local.x;
        scaled.y = ((Vector4 *)(drone + 0x120))->y * local.y;
        scaled.z = ((Vector4 *)(drone + 0x120))->z * local.z;
        XformVecOrientation(drone + 0x10, &scaled, (Vector4 *)(drone + 0x130));
        if (*(s32 *)(drone + 0x78) <= 0) {
            Thing_ProcessEndEvent(drone, *(u8 **)(*(u8 **)(drone + 0xC0) + 0x10), collision, (Vector4 *)(drone + 0x130));
            Thing_Release((s32)drone);
        }
        *(f32 *)(drone + 0x180) = 0.0f;
        *(s32 *)(drone + 0x17C) = 0;
    }
}

void Drone_DynamicRotation(u8 *drone) {
    void QuaternionToSubMatrix(void *quat, void *mtx);
    void PhysicalObject_DynamicRotation(u8 *obj);
    Vector4 quat;
    Matrix4 mtx;

    if (*(u8 *)(drone + 0x1DC) == 2) {
        if (!(*(u32 *)(drone + 0x74) & 0x10)) {
            *(u32 *)(drone + 0x74) |= 0x10;
            quat = *(Vector4 *)(drone + 0xE0);
            QuaternionToSubMatrix(&quat, &mtx);
            mtx.m[3][0] = ((Thing *)drone)->mtx.m[3][0];
            mtx.m[3][1] = ((Thing *)drone)->mtx.m[3][1];
            mtx.m[3][2] = ((Thing *)drone)->mtx.m[3][2];
            ((Thing *)drone)->quat = quat;
            ((Thing *)drone)->mtx = mtx;
        }
    } else {
        PhysicalObject_DynamicRotation(drone);
    }
}

f32 GetDampFactor(u8 type, u32 n) {
    f32 f = 1.0f;
    u32 i = n;
    f32 result;

    if (type <= 8) {
        while (i >= 10) {
            f *= g_frictionTable[type][9];
            i -= 10;
        }
        result = f * g_frictionTable[type][i];
    } else {
        while (type > 8) {
            f *= GetDampFactor(8, n);
            type -= 8;
        }
        result = f * GetDampFactor(type, n);
    }
    return result;
}

f32 CarA_GetImpactMultiplier(void *car, void *other, f32 scale) {
    f32 PSVECDotProduct(void *a, void *b);
    f32 impact;

    impact = scale * PSVECDotProduct((u8 *)car + 0x20, (u8 *)other + 0x10);
    if (impact < 0.0f) {
        return 1.0f;
    }
    return 1.0f - impact;
}

