f32 RayHitsPoly(Vector4 *start, Vector4 *dir, Vector4 *poly, f32 t) {
    typedef struct Poly {
        Vector4 plane;
        Vector4 *verts;
        u32 numVerts;
    } Poly;
    f32 PSVECDotProduct(Vector4 *a, Vector4 *b);
    void PSVECSubtract(Vector4 *a, Vector4 *b, Vector4 *out);
    void PSVECCrossProduct(Vector4 *a, Vector4 *b, Vector4 *out);
    f32 Distance_Plane(void *plane, void *point);
    Vector4 edge;
    Vector4 normal;
    u32 i;
    u32 prev;
    Poly *p = (Poly *)poly;
    f32 denom;
    f32 d0;
    f32 d1;
    f32 base;
    f32 a;
    f32 b;

    denom = PSVECDotProduct(&p->plane, dir);
    if (denom >= 0.0f) {
        return t;
    }
    d0 = Distance_Plane(p, start);
    if (d0 < 0.0f) {
        return t;
    }
    d1 = denom * t + d0;
    if (d1 > 0.0f) {
        return t;
    }
    prev = p->numVerts - 1;
    for (i = 0; i < p->numVerts; i++) {
        PSVECSubtract(&p->verts[i], &p->verts[prev], &edge);
        PSVECCrossProduct(dir, &edge, &normal);
        base = PSVECDotProduct(&normal, start);
        a = PSVECDotProduct(&normal, &p->verts[i]);
        b = PSVECDotProduct(&normal, &p->verts[(u32)p->verts[i].w]);
        if ((a - base) * (b - base) > 0.0f) {
            return t;
        }
        prev = i;
    }
    if (d0 && t && d0 != d1) {
        return t * (d0 / (d0 - d1));
    }
    return 0.0f;
}

#pragma push
#pragma use_lmw_stmw on
f32 OOBHitsPoly(PolyOBox *box, CollisionPoly *poly, Vector4 *vel, PolyHit *hit, f32 maxT) {
    void PSVECSubtract(Vector4 *a, Vector4 *b, Vector4 *out);
    void PSVECAdd(Vector4 *a, Vector4 *b, Vector4 *out);
    f32 PSVECSquareMag(Vector4 *v);
    void PSVECNormalize(Vector4 *src, Vector4 *dst);
    f32 PSVECDotProduct(Vector4 *a, Vector4 *b);
    void PSVECCrossProduct(Vector4 *a, Vector4 *b, Vector4 *axb);
    void Create_Plane(Vector4 *plane, Vector4 *normal, Vector4 *point);
    f32 Distance_Plane(Vector4 *plane, Vector4 *point);
    u8 FloatsEqual(f32 a, f32 b, f32 eps);
    s8 CollisionTriCache_Get(u32 tri0, u32 tri1, Vector4 *a, Vector4 *b);
    void CollisionTriCache_Set(u32 tri0, u32 tri1, Vector4 *a, Vector4 *b);
    s32 Collision_ProcessDividingAxis(DividingAxis *axis);
    f32 planeD;
    DividingAxis da;
    Vector4 edge;
    Vector4 axis;
    Vector4 p0;
    Vector4 p1;
    Vector4 dir;
    Vector4 start;
    Vector4 end;
    Vector4 plane;
    Vector4 cross;
    Vector4 corner;
    Vector4 cornerEnd;
    u8 hiIdx;
    s32 j;
    u8 type;
    u32 cornerIdx;
    u8 axisIdx;
    u8 edgeIdx;
    u8 edgeVert;
    s32 i;
    u8 loIdx;
    u8 vert;
    u8 minIdx;
    u8 maxIdx;
    u32 k;
    s32 prev;
    f32 a;
    f32 b;
    f32 d;
    f32 d2;

    planeD = -poly->plane.w;
    da.tEnter = 0.0f;
    da.tExit = maxT;
    type = 0;
    axisIdx = 0;
    vert = 99;
    edgeIdx = 99;
    for (i = 0; i < 3; i++) {
        minIdx = 0;
        maxIdx = 0;
        da.minA = da.maxA = PSVECDotProduct(box->axis[i], &poly->verts[0]);
        for (k = 1; k < poly->numVerts; k++) {
            d = PSVECDotProduct(box->axis[i], &poly->verts[k]);
            if (d < da.minA) {
                da.minA = d;
                minIdx = k;
            } else if (d > da.maxA) {
                da.maxA = d;
                maxIdx = k;
            }
        }
        da.dir = -PSVECDotProduct(box->axis[i], vel);
        d = PSVECDotProduct(box->axis[i], &box->center);
        da.maxB = d + box->extent[i];
        da.minB = d - box->extent[i];
        switch ((u8)Collision_ProcessDividingAxis(&da)) {
        case 0:
            return maxT;
        case 2:
            vert = minIdx;
            axisIdx = i + 3;
            type = 1;
            break;
        case 3:
            vert = maxIdx;
            axisIdx = i;
            type = 1;
            break;
        }
    }
    cornerIdx = 0;
    da.minB = da.maxB = PSVECDotProduct(&poly->plane, &box->corners[0]);
    for (k = 1; k < 8; k++) {
        d = PSVECDotProduct(&poly->plane, &box->corners[k]);
        if (d < da.minB) {
            da.minB = d;
            cornerIdx = (u8)k;
        } else if (d > da.maxB) {
            da.maxB = d;
        }
    }
    da.dir = -PSVECDotProduct(&poly->plane, vel);
    da.minA = planeD;
    da.maxA = planeD;
    switch ((u8)Collision_ProcessDividingAxis(&da)) {
    case 0:
        return maxT;
    case 2:
        type = 2;
        break;
    case 3:
        type = 2;
        break;
    }
    for (j = 0, prev = poly->numVerts - 1; j < (s32)poly->numVerts; prev = j, j++) {
        PSVECSubtract(&poly->verts[j], &poly->verts[prev], &edge);
        for (i = 0; i < 3; i++) {
            u8 edgeMax = 0;
            u8 edgeMin = 0;
            s32 m;

            PSVECCrossProduct(box->axis[i], &edge, &axis);
            da.minB = da.maxB = PSVECDotProduct(&axis, &box->corners[0]);
            for (m = 1; m < 8; m++) {
                d = PSVECDotProduct(&axis, &box->corners[m]);
                if (d < da.minB) {
                    da.minB = d;
                    edgeMin = m;
                } else if (d > da.maxB) {
                    edgeMax = m;
                    da.maxB = d;
                }
            }
            a = PSVECDotProduct(&axis, &poly->verts[j]);
            b = PSVECDotProduct(&axis, &poly->verts[(u32)poly->verts[j].w]);
            if (a > b) {
                da.minA = b;
                hiIdx = j;
                da.maxA = a;
                loIdx = poly->verts[j].w;
            } else {
                da.minA = a;
                loIdx = j;
                da.maxA = b;
                hiIdx = poly->verts[j].w;
            }
            da.dir = -PSVECDotProduct(&axis, vel);
            switch ((u8)Collision_ProcessDividingAxis(&da)) {
            case 0:
                return maxT;
            case 2:
                edgeVert = loIdx;
                edgeIdx = j;
                axisIdx = i;
                cornerIdx = edgeMax;
                type = 3;
                break;
            case 3:
                edgeVert = hiIdx;
                edgeIdx = j;
                axisIdx = i;
                cornerIdx = edgeMin;
                type = 3;
                break;
            }
        }
    }
    if (hit != NULL && da.tEnter < maxT) {
        hit->type = type;
        hit->unk28 = (*(u32 **)(*(u8 **)g_worldData.world + 0x5C))[poly->material];
        box->unkCC = (u32)poly;
        switch (type) {
        case 1:
            hit->pos = poly->verts[vert];
            hit->normal = *box->axis[axisIdx % 3];
            if (axisIdx >= 3) {
                hit->normal.x *= -1.0f;
                hit->normal.y *= -1.0f;
                hit->normal.z *= -1.0f;
            }
            CollisionTriCache_Set((u32)box, (u32)poly, &hit->pos, &hit->normal);
            break;
        case 2:
            hit->pos = box->corners[cornerIdx];
            hit->pos.x += vel->x * da.tEnter;
            hit->pos.y += vel->y * da.tEnter;
            hit->pos.z += vel->z * da.tEnter;
            hit->normal = poly->plane;
            CollisionTriCache_Set((u32)box, (u32)poly, &hit->pos, &hit->normal);
            break;
        case 3:
            p0 = poly->verts[edgeIdx];
            p1 = poly->verts[(edgeIdx + poly->numVerts - 1) % poly->numVerts];
            PSVECCrossProduct(box->axis[axisIdx], vel, &cross);
            Create_Plane(&plane, &cross, &box->corners[cornerIdx]);
            start = poly->verts[edgeVert];
            PSVECSubtract(&p1, &p0, &dir);
            PSVECAdd(&start, &dir, &end);
            a = Distance_Plane(&plane, &start);
            b = Distance_Plane(&plane, &end);
            corner = box->corners[cornerIdx];
            cornerEnd.x = corner.x + box->axis[axisIdx]->x;
            cornerEnd.y = corner.y + box->axis[axisIdx]->y;
            cornerEnd.z = corner.z + box->axis[axisIdx]->z;
            d = Distance_Plane(&poly->plane, &corner);
            d2 = Distance_Plane(&poly->plane, &cornerEnd);
            if (FloatsEqual(d, 0.0f, 0.001f) && FloatsEqual(d2, 0.0f, 0.001f)) {
                hit->pos = box->corners[cornerIdx];
                hit->pos.x += vel->x * da.tEnter;
                hit->pos.y += vel->y * da.tEnter;
                hit->pos.z += vel->z * da.tEnter;
                hit->normal = poly->plane;
                CollisionTriCache_Set((u32)box, (u32)poly, &hit->pos, &hit->normal);
            } else {
                if (FloatsEqual(a - b, 0.0f, 0.0001f)) {
                    hit->pos = poly->verts[edgeVert];
                    hit->normal.x = -vel->x;
                    hit->normal.y = -vel->y;
                    hit->normal.z = -vel->z;
                    if (PSVECSquareMag(&hit->normal)) {
                        PSVECNormalize(&hit->normal, &hit->normal);
                    }
                } else {
                    d = a / (a - b);
                    hit->pos.x = dir.x * d + start.x;
                    hit->pos.y = dir.y * d + start.y;
                    hit->pos.z = dir.z * d + start.z;
                    PSVECCrossProduct(box->axis[axisIdx], &dir, &hit->normal);
                    if (PSVECSquareMag(&hit->normal)) {
                        PSVECNormalize(&hit->normal, &hit->normal);
                    }
                    if (PSVECDotProduct(&hit->normal, vel) > 0.0f) {
                        hit->normal.x *= -1.0f;
                        hit->normal.y *= -1.0f;
                        hit->normal.z *= -1.0f;
                    }
                }
                CollisionTriCache_Set((u32)box, (u32)poly, &hit->pos, &hit->normal);
            }
            break;
        default:
            hit->type = 0xFF;
            if (!CollisionTriCache_Get((u32)box, (u32)poly, &hit->pos, &hit->normal)) {
                hit->pos = poly->verts[0];
                hit->normal = poly->plane;
            }
            break;
        }
    }
    return da.tEnter;
}
#pragma pop

typedef struct OBoxZT {
    Vector4 center;
    Vector4 corners[8];
    f32 extents[4];
    Vector4 *axes[3];
} OBoxZT;

typedef struct PolyZT {
    Vector4 plane;
    Vector4 *verts;
    u32 numVerts;
} PolyZT;

typedef struct HitZT {
    Vector4 pos;
    Vector4 normal;
} HitZT;

s8 OBoxHitsPolyZeroTime(OBoxZT *box, PolyZT *p, HitZT *hit) {
    f32 PSVECDotProduct(void *a, void *b);
    void PSVECSubtract(void *a, void *b, void *out);
    void PSVECCrossProduct(void *a, void *b, void *out);
    void PSVECNormalize(void *a, void *out);
    f32 PSVECSquareMag(void *v);
    f32 Sqrt(f32 x);
    void Create_Plane(void *plane, void *normal, void *point);
    f32 Distance_Plane(void *plane, void *point);
    Vector4 edgeDir;
    Vector4 n;
    Vector4 pt;
    Vector4 c2;
    Vector4 e;
    Vector4 c1;
    Vector4 plane;
    Vector4 tmp;
    f32 best;
    f32 planeD;
    f32 d;
    f32 t;
    s32 i;
    s32 k;
    s32 prev;
    u8 type;
    u32 feature;
    u8 axis;
    u8 edge;
    s8 flip;

    best = -99999.9f;
    planeD = -p->plane.w;
    type = 0;
    axis = 0;
    edge = 0;
    for (i = 0; i < 3; i++) {
        u32 j;
        u8 minIdx = 0;
        u8 maxIdx = 0;
        f32 min;
        f32 max;
        f32 c;
        f32 lo;
        f32 hi;
        min = max = PSVECDotProduct(box->axes[i], &p->verts[0]);
        for (j = 1; j < p->numVerts; j++) {
            d = PSVECDotProduct(box->axes[i], &p->verts[j]);
            if (d < min) {
                min = d;
                minIdx = j;
            } else if (d > max) {
                max = d;
                maxIdx = j;
            }
        }
        c = PSVECDotProduct(box->axes[i], box);
        lo = c - box->extents[i];
        hi = c + box->extents[i];
        if (max < lo || hi < min) {
            return 0;
        }
        if (min < hi && min - hi > best) {
            best = min - hi;
            feature = minIdx;
            axis = i;
            type = 1;
            flip = 0;
        }
        if (lo < max && lo - max > best) {
            best = lo - max;
            feature = maxIdx;
            axis = i;
            type = 1;
            flip = 1;
        }
    }
    {
        u32 j;
        u8 minIdx = 0;
        f32 min;
        f32 max;
        min = max = PSVECDotProduct(p, &box->corners[0]);
        for (j = 1; j < 8; j++) {
            d = PSVECDotProduct(p, &box->corners[j]);
            if (d < min) {
                min = d;
                minIdx = j;
            } else if (d > max) {
                max = d;
            }
        }
        if (planeD < min || max < planeD) {
            return 0;
        }
        if (planeD < max && planeD - max > best) {
            best = planeD - max;
            feature = minIdx;
            type = 2;
        }
        if (min < planeD && min - planeD > best) {
            best = min - planeD;
            feature = minIdx;
            type = 2;
        }
    }
    for (k = 0, prev = p->numVerts - 1; k < (s32)p->numVerts; prev = k++) {
        PSVECSubtract(&p->verts[k], &p->verts[prev], &edgeDir);
        for (i = 0; i < 3; i++) {
            s32 j;
            u8 maxIdx = 0;
            u8 minIdx = 0;
            f32 min;
            f32 max;
            f32 lo;
            f32 hi;
            f32 a;
            f32 mag;
            PSVECCrossProduct(box->axes[i], &edgeDir, &n);
            mag = PSVECSquareMag(&n);
            if (!(mag < 0.0001f)) {
                mag = 1.0f / Sqrt(mag);
                n.x *= mag;
                n.y *= mag;
                n.z *= mag;
                min = max = PSVECDotProduct(&n, &box->corners[0]);
                for (j = 1; j < 8; j++) {
                    d = PSVECDotProduct(&n, &box->corners[j]);
                    if (d < min) {
                        min = d;
                        minIdx = j;
                    } else if (d > max) {
                        maxIdx = j;
                        max = d;
                    }
                }
                a = PSVECDotProduct(&n, &p->verts[k]);
                hi = PSVECDotProduct(&n, &p->verts[(u32)p->verts[k].w]);
                if (a > hi) {
                    lo = hi;
                    hi = a;
                } else {
                    lo = a;
                }
                if (hi < min || max < lo) {
                    return 0;
                }
                if (lo < max && lo - max > best) {
                    best = lo - max;
                    axis = i;
                    edge = k;
                    feature = maxIdx;
                    type = 3;
                }
                if (min < hi && min - hi > best) {
                    best = min - hi;
                    axis = i;
                    edge = k;
                    feature = minIdx;
                    type = 3;
                }
            }
        }
    }
    if (hit != NULL && best < 0.0f) {
        switch (type) {
        case 1:
            hit->pos = p->verts[feature];
            hit->normal = *box->axes[axis];
            if (flip) {
                hit->normal.x *= -1.0f;
                hit->normal.y *= -1.0f;
                hit->normal.z *= -1.0f;
            }
            break;
        case 2:
            hit->pos = box->corners[feature];
            hit->normal = p->plane;
            break;
        case 3:
            pt = box->corners[feature];
            PSVECSubtract(&p->verts[edge], &p->verts[(edge + (p->numVerts - 1)) % p->numVerts], &e);
            PSVECCrossProduct(&e, box->axes[axis], &c1);
            PSVECCrossProduct(&e, &c1, &c2);
            Create_Plane(&plane, &c2, &p->verts[edge]);
            d = Distance_Plane(&plane, &pt);
            t = -d / PSVECDotProduct(&plane, box->axes[axis]);
            pt.x += box->axes[axis]->x * t;
            pt.y += box->axes[axis]->y * t;
            pt.z += box->axes[axis]->z * t;
            hit->pos = pt;
            hit->normal = c1;
            if (PSVECSquareMag(&hit->normal)) {
                PSVECNormalize(&hit->normal, &hit->normal);
            }
            PSVECSubtract(box, hit, &tmp);
            if (PSVECDotProduct(&tmp, &hit->normal) < 0.0f) {
                hit->normal.x *= -1.0f;
                hit->normal.y *= -1.0f;
                hit->normal.z *= -1.0f;
            }
            break;
        }
    }
    return 1;
}

s8 RayHitsTerrain(Vector4 *start, Vector4 *end, void *arg2, void *arg3) {
    s8 RayHitsTerrain_Aux3(void *, void *, void *, void *);
    void PSVECSubtract(Vector4 *a, Vector4 *b, Vector4 *out);
    Vector4 dir;

    PSVECSubtract(end, start, &dir);
    return RayHitsTerrain_Aux3(start, &dir, arg2, arg3);
}

s8 OBoxHitsTerrain(void *obox, Vector4 *vel, f32 *t, void *info) {
    typedef struct {
        Vector4 origin;
        u8 unk10[0x20 - 0x10];
        u8 *cells;
        u8 unk24[0x28 - 0x24];
        f32 sizeX;
        f32 sizeY;
        f32 sizeZ;
        s32 numX;
        s32 numY;
        s32 numZ;
        s32 *cellIndex;
    } Grid;
    void MinMaxVec(Vector4 *min, Vector4 *max, Vector4 *v);
    void World_NextSweep(void);
    f32 _fabs(f32 x);
    s8 OBoxHitsCell(void *obox, Vector4 *vel, void *cell, f32 *time, void *arg4);
    Vector4 bounds[2];
    f32 best;
    s32 numX;
    s32 numY;
    s32 numZ;
    s32 x0;
    s32 x1;
    s32 y0;
    s32 y1;
    s32 z0;
    s32 z1;
    s32 x;
    s32 y;
    s32 z;
    s32 n;
    s32 index;
    u32 i;
    Grid *grid;
    s8 hit;
    f32 oy;
    f32 dtz;
    f32 ox;
    f32 dtx;
    f32 oz;
    f32 dty;
    f32 sx;
    f32 sy;
    f32 spanX;
    f32 sz;
    f32 spanZ;
    f32 tx;
    f32 tz;
    f32 spanY;
    f32 ty;

    grid = *(Grid **)g_worldData.world;
    if (g_worldData.world == NULL || grid == NULL) {
        return 0;
    }
    numX = grid->numX;
    numY = grid->numY;
    numZ = grid->numZ;
    hit = 0;
    ox = grid->origin.x;
    oy = grid->origin.y;
    oz = grid->origin.z;
    sx = grid->sizeX;
    sy = grid->sizeY;
    sz = grid->sizeZ;
    bounds[0].x = 99999.0f;
    bounds[0].y = 99999.0f;
    bounds[0].z = 99999.0f;
    bounds[1].x = -99999.0f;
    bounds[1].y = -99999.0f;
    bounds[1].z = -99999.0f;
    for (i = 0; i < 8; i++) {
        MinMaxVec(&bounds[0], &bounds[1], (Vector4 *)obox + 1 + i);
    }
    World_NextSweep();
    best = *t;
    x0 = (bounds[0].x - ox) / sx;
    x1 = (bounds[1].x - ox) / sx;
    y0 = (bounds[0].y - oy) / sy;
    y1 = (bounds[1].y - oy) / sy;
    z0 = (bounds[0].z - oz) / sz;
    z1 = (bounds[1].z - oz) / sz;
    if (x1 < 0) {
        return 0;
    }
    if ((u32)x1 > (u32)grid->numX) {
        x1 = grid->numX - 1;
    }
    if (x0 < 0) {
        x0 = 0;
    } else if (x0 > x1) {
        x0 = x1;
    }
    if (y1 < 0) {
        return 0;
    }
    if ((u32)y1 > (u32)grid->numY) {
        y1 = grid->numY - 1;
    }
    if (y0 < 0) {
        y0 = 0;
    } else if (y0 > y1) {
        y0 = y1;
    }
    if (z1 < 0) {
        return 0;
    }
    if ((u32)z1 > (u32)grid->numZ) {
        z1 = grid->numZ - 1;
    }
    if (z0 < 0) {
        z0 = 0;
    } else if (z0 > z1) {
        z0 = z1;
    }
    for (x = x0; x <= x1; x++) {
        for (y = y0; y <= y1; y++) {
            for (z = z0; z <= z1; z++) {
                grid = *(Grid **)g_worldData.world;
                if (x < 0 || x >= grid->numX) {
                    index = -1;
                } else if (y < 0 || y >= grid->numY) {
                    index = -1;
                } else if (z < 0 || z >= grid->numZ) {
                    index = -1;
                } else {
                    index = z * grid->numX + grid->numZ * (y * grid->numX) + x;
                }
                if (OBoxHitsCell(obox, vel, index == -1 ? grid->cells : grid->cells + grid->cellIndex[index] * 0x50, &best, info)) {
                    hit = 1;
                }
            }
        }
    }
    if (hit) {
        *t = best;
        return 1;
    }
    tx = ty = tz = *t;
    if (vel->x >= 0.0f) {
        if (x1 < numX - 1 && 0.0f != vel->x) {
            tx = (ox + ((f32)(x1 + 1) * sx - bounds[1].x)) / vel->x;
        }
    } else if (x0 > 0) {
        tx = (ox + ((f32)x0 * sx - bounds[0].x)) / vel->x;
    }
    if (vel->y >= 0.0f) {
        if (y1 < numY - 1 && 0.0f != vel->y) {
            ty = (oy + ((f32)(y1 + 1) * sy - bounds[1].y)) / vel->y;
        }
    } else if (y0 > 0) {
        ty = (oy + ((f32)y0 * sy - bounds[0].y)) / vel->y;
    }
    if (vel->z >= 0.0f) {
        if (z1 < numZ - 1 && 0.0f != vel->z) {
            tz = (oz + ((f32)(z1 + 1) * sz - bounds[1].z)) / vel->z;
        }
    } else if (z0 > 0) {
        tz = (oz + ((f32)z0 * sz - bounds[0].z)) / vel->z;
    }
    spanX = (bounds[1].x - bounds[0].x) / sx;
    spanY = (bounds[1].y = bounds[0].y) / sy;
    spanZ = (bounds[1].z - bounds[0].z) / sz;
    if (0.0f != vel->x) {
        dtx = _fabs(sx / vel->x);
    } else {
        dtx = *t;
    }
    if (0.0f != vel->y) {
        dty = _fabs(sx / vel->y);
    } else {
        dty = *t;
    }
    if (0.0f != vel->z) {
        dtz = _fabs(sz / vel->z);
    } else {
        dtz = *t;
    }
    while (tx < best || ty < best || tz < best) {
        if (tx < tz && tx < ty) {
            tx += dtx;
            if (vel->x > 0.0f) {
                n = ++x1;
                x0 = (f32)x1 - spanX;
                if (x1 >= numX) {
                    tx = best;
                }
            } else {
                n = --x0;
                x1 = (f32)x0 + spanX;
                if (x0 <= 0) {
                    tx = best;
                }
            }
            if (n >= 0 && n < numX) {
                for (y = y0; y <= y1; y++) {
                    for (z = z0; z <= z1; z++) {
                        grid = *(Grid **)g_worldData.world;
                        if (n < 0 || n >= grid->numX) {
                            index = -1;
                        } else if (y < 0 || y >= grid->numY) {
                            index = -1;
                        } else if (z < 0 || z >= grid->numZ) {
                            index = -1;
                        } else {
                            index = z * grid->numX + grid->numZ * (y * grid->numX) + n;
                        }
                        if (OBoxHitsCell(obox, vel, index == -1 ? grid->cells : grid->cells + grid->cellIndex[index] * 0x50, &best, info)) {
                            hit = 1;
                        }
                    }
                }
                if (hit) {
                    *t = best;
                    return 1;
                }
            }
        } else if (tz < tx && tz < ty) {
            tz += dtz;
            if (vel->z > 0.0f) {
                n = ++z1;
                z0 = (f32)z1 - spanZ;
                if (z1 >= numZ) {
                    tz = best;
                }
            } else {
                n = --z0;
                z1 = (f32)z0 + spanZ;
                if (z0 <= 0) {
                    tz = best;
                }
            }
            if (n >= 0 && n < numZ) {
                for (x = x0; x <= x1; x++) {
                    for (y = y0; y <= y1; y++) {
                        grid = *(Grid **)g_worldData.world;
                        if (x < 0 || x >= grid->numX) {
                            index = -1;
                        } else if (y < 0 || y >= grid->numY) {
                            index = -1;
                        } else if (n < 0 || n >= grid->numZ) {
                            index = -1;
                        } else {
                            index = n * grid->numX + grid->numZ * (y * grid->numX) + x;
                        }
                        if (OBoxHitsCell(obox, vel, index == -1 ? grid->cells : grid->cells + grid->cellIndex[index] * 0x50, &best, info)) {
                            hit = 1;
                        }
                    }
                }
                if (hit) {
                    *t = best;
                    return 1;
                }
            }
        } else {
            ty += dty;
            if (vel->y > 0.0f) {
                n = ++y1;
                y0 = (f32)y1 - spanY;
                if (y1 >= numY) {
                    ty = best;
                }
            } else {
                n = --y0;
                y1 = (f32)y0 + spanY;
                if (y0 <= 0) {
                    ty = best;
                }
            }
            if (n >= 0 && n < numY) {
                for (x = x0; x <= x1; x++) {
                    for (z = z0; z <= z1; z++) {
                        grid = *(Grid **)g_worldData.world;
                        if (x < 0 || x >= grid->numX) {
                            index = -1;
                        } else if (n < 0 || n >= grid->numY) {
                            index = -1;
                        } else if (z < 0 || z >= grid->numZ) {
                            index = -1;
                        } else {
                            index = z * grid->numX + grid->numZ * (n * grid->numX) + x;
                        }
                        if (OBoxHitsCell(obox, vel, index == -1 ? grid->cells : grid->cells + grid->cellIndex[index] * 0x50, &best, info)) {
                            hit = 1;
                        }
                    }
                }
                if (hit) {
                    *t = best;
                    return 1;
                }
            }
        }
    }
    return 0;
}

s8 OBoxHitsCellZeroTimeEdgesOnly(void *obox, void *cell, void *arg2);
s8 OBoxHitsTerrainZeroTimeEdgesOnly(void *obox, void *arg1) {
    typedef struct Grid {
        Vector4 origin;
        u8 unk10[0x20 - 0x10];
        u8 *cells;
        u8 unk24[0x28 - 0x24];
        f32 sizeX;
        f32 sizeY;
        f32 sizeZ;
        s32 numX;
        s32 numY;
        s32 numZ;
        s32 *cellIndex;
    } Grid;
    void MinMaxVec(Vector4 *min, Vector4 *max, Vector4 *v);
    void World_NextSweep(void);
    Grid *grid;
    Vector4 bounds[2];
    f32 ox;
    f32 oy;
    f32 oz;
    f32 sx;
    f32 sy;
    f32 sz;
    s32 x;
    s32 x0;
    s32 x1;
    s32 y;
    s32 y0;
    s32 y1;
    s32 z;
    s32 z0;
    s32 z1;
    u32 i;
    s32 index;

    if (g_worldData.world == NULL || *(Grid **)g_worldData.world == NULL) {
        return 0;
    }
    grid = *(Grid **)g_worldData.world;
    ox = grid->origin.x;
    oy = grid->origin.y;
    oz = grid->origin.z;
    sx = grid->sizeX;
    sy = grid->sizeY;
    sz = grid->sizeZ;
    bounds[0].x = 99999.0f;
    bounds[0].y = 99999.0f;
    bounds[0].z = 99999.0f;
    bounds[0].w = 99999.0f;
    bounds[1].x = -99999.0f;
    bounds[1].y = -99999.0f;
    bounds[1].z = -99999.0f;
    bounds[1].w = -99999.0f;
    for (i = 0; i < 8; i++) {
        MinMaxVec(&bounds[0], &bounds[1], (Vector4 *)obox + 1 + i);
    }
    World_NextSweep();
    x0 = (bounds[0].x - ox) / sx;
    x1 = (bounds[1].x - ox) / sx;
    y0 = (bounds[0].y - oy) / sy;
    y1 = (bounds[1].y - oy) / sy;
    z0 = (bounds[0].z - oz) / sz;
    z1 = (bounds[1].z - oz) / sz;
    for (x = x0; x <= x1; x++) {
        for (y = y0; y <= y1; y++) {
            for (z = z0; z <= z1; z++) {
                grid = *(Grid **)g_worldData.world;
                if (x < 0 || x >= grid->numX) {
                    index = -1;
                } else if (y < 0 || y >= grid->numY) {
                    index = -1;
                } else if (z < 0 || z >= grid->numZ) {
                    index = -1;
                } else {
                    index = z * grid->numX + grid->numZ * (y * grid->numX) + x;
                }
                if (OBoxHitsCellZeroTimeEdgesOnly(obox, index == -1 ? grid->cells : grid->cells + grid->cellIndex[index] * 0x50, arg1)) {
                    return 1;
                }
            }
        }
    }
    return 0;
}

