        u8 unkBC[0xBF - 0xBC];
        u8 unkBF;
        f32 unkC0;
        u8 unkC4[0xCC - 0xC4];
        u8 motion[0x130 - 0xCC];
        f32 unk130;
        u8 unk134[0x190 - 0x134];
        Vector4 startPos;
        u8 unk1A0[0x1B0 - 0x1A0];
