        impact.source = source;
        impact.unk28 = 0;
        force *= (*(f32 (**)(u8 *))(*(u8 **)(thing + 0x8C) + 0x14))(thing);
        (*(void (**)(u8 *, void *, s32, f32))(*(u8 **)(thing + 0x8C) + 0x18))(thing, &impact, damageType, force);
