                mtx4.v[1].y *= -1.0f;
                mtx4.v[1].z *= -1.0f;
                mtx4.v[2].x *= -1.0f;
                mtx4.v[2].y *= -1.0f;
                mtx4.v[2].z *= -1.0f;
