static inline void Grid_GetCell(Vector4 *pos, s32 *cellX, s32 *cellZ) {
    f32 fx;
    f32 fz;

    fx = (pos->x - ((GridManager *)gGridManager)->min.x) / ((GridManager *)gGridManager)->cellSizeX;
    if (fx < 0.0f) {
        fx = 0.0f;
    } else if (fx >= (f32)((GridManager *)gGridManager)->numX) {
        fx = (f32)((GridManager *)gGridManager)->numX - 1.0f;
    }
    fz = (pos->z - ((GridManager *)gGridManager)->min.z) / ((GridManager *)gGridManager)->cellSizeZ;
    if (fz < 0.0f) {
        fz = 0.0f;
    } else if (fz >= (f32)((GridManager *)gGridManager)->numZ) {
        fz = (f32)((GridManager *)gGridManager)->numZ - 1.0f;
    }
    *cellX = fx;
    *cellZ = fz;
}

static inline void Grid_PushFreeNode(GridNode *node) {
    node->next = ((GridManager *)gGridManager)->freeNodes;
    ((GridManager *)gGridManager)->freeNodes = node;
}

static inline void Grid_RemoveNodes(GridObject *obj) {
    GridNode *node;
    GridNode *next;

    for (node = obj->nodes; node != NULL; node = next) {
        next = node->objNext;
        if (node->next != NULL) {
            node->next->prev = node->prev;
        }
        if (node->prev != NULL) {
            node->prev->next = node->next;
        } else {
            node->cell->head = node->next;
        }
        node->cell->count--;
        Grid_PushFreeNode(node);
    }
}

static inline void Grid_InsertNodes(GridObject *obj) {
    GridNode *node;
    GridNode *newNode;
    GridNode *prev;
    u32 x;
    u32 z;

    prev = NULL;
    for (x = obj->x0; x <= obj->x1; x++) {
        for (z = obj->z0; z <= obj->z1; z++) {
            node = ((GridManager *)gGridManager)->freeNodes;
            newNode = NULL;
            if (node != NULL) {
                ((GridManager *)gGridManager)->freeNodes = node->next;
                newNode = node;
                *(GridResult *)node = *(GridResult *)obj;
                node->objNext = prev;
                node->cell = &((GridManager *)gGridManager)->cells[node->data][x * ((GridManager *)gGridManager)->numZ + z];
                node->prev = NULL;
                node->next = ((GridManager *)gGridManager)->cells[node->data][x * ((GridManager *)gGridManager)->numZ + z].head;
                if (node->next != NULL) {
                    node->next->prev = node;
                }
                ((GridManager *)gGridManager)->cells[node->data][x * ((GridManager *)gGridManager)->numZ + z].head = node;
                ((GridManager *)gGridManager)->cells[node->data][x * ((GridManager *)gGridManager)->numZ + z].count++;
            }
            prev = newNode;
        }
    }
    obj->nodes = prev;
}

static inline void Grid_PushFreeObject(GridObject *object) {
    object->next = ((GridManager *)gGridManager)->freeObjects;
    ((GridManager *)gGridManager)->freeObjects = object;
    ((GridManager *)gGridManager)->numFreeObjects++;
}

void Grid_Init(Vector4 *min, Vector4 *max, u32 numX, u32 numZ) {
    u16 i;
    u16 j;
    GridManager *gm;

    ((GridManager *)gGridManager)->numX = numX;
    ((GridManager *)gGridManager)->numZ = numZ;
    ((GridManager *)gGridManager)->numCells = numX * numZ;
    ((GridManager *)gGridManager)->min = *min;
    ((GridManager *)gGridManager)->max = *max;
    ((GridManager *)gGridManager)->cellSizeX = (max->x - min->x) / (f32)numX;
    ((GridManager *)gGridManager)->cellSizeZ = (max->z - min->z) / (f32)numZ;
    for (i = 0; i < 7; i++) {
        for (j = 0; j < ((GridManager *)gGridManager)->numCells; j++) {
            ((GridManager *)gGridManager)->cells[i][j].count = 0;
            ((GridManager *)gGridManager)->cells[i][j].head = NULL;
        }
    }
    gm = (GridManager *)gGridManager;
    gm->freeNodes = NULL;
    for (i = 0; i < 4048; i++) {
        Grid_PushFreeNode(&gm->nodes[i]);
    }
    gm = (GridManager *)gGridManager;
    gm->freeObjects = NULL;
    gm->numFreeObjects = 0;
    for (i = 0; i < 1024; i++) {
        Grid_PushFreeObject(&gm->objects[i]);
    }
}

