GridObject *Grid_AddObject(u32 data, u32 id, void *min, void *max) {
    u32 z;
    u32 x;
    GridObject *obj;
    GridObject *result = NULL;
    GridNode *prev;
    GridNode *newNode;
    GridNode *node;

    obj = ((GridManager *)gGridManager)->freeObjects;
    if (obj != NULL) {
        ((GridManager *)gGridManager)->freeObjects = obj->next;
        ((GridManager *)gGridManager)->numFreeObjects--;
        Grid_GetCell(min, &obj->x0, &obj->z0);
        Grid_GetCell(max, &obj->x1, &obj->z1);
        obj->data = data;
        obj->id = id;
        prev = NULL;
        for (x = obj->x0; x <= obj->x1; x++) {
            for (z = obj->z0; z <= obj->z1; z++) {
                node = ((GridManager *)gGridManager)->freeNodes;
                newNode = NULL;
                if (node != NULL) {
                    ((GridManager *)gGridManager)->freeNodes = node->next;
                    newNode = node;
                    *(GridResult *)node = *(GridResult *)obj;
                    node->objNext = prev;
                    node->cell = &((GridManager *)gGridManager)->cells[node->data][x * ((GridManager *)gGridManager)->numZ + z];
                    node->prev = NULL;
                    node->next = ((GridManager *)gGridManager)->cells[node->data][x * ((GridManager *)gGridManager)->numZ + z].head;
                    if (node->next != NULL) {
                        node->next->prev = node;
                    }
                    ((GridManager *)gGridManager)->cells[node->data][x * ((GridManager *)gGridManager)->numZ + z].head = node;
                    ((GridManager *)gGridManager)->cells[node->data][x * ((GridManager *)gGridManager)->numZ + z].count++;
                }
                prev = newNode;
            }
        }
        obj->nodes = prev;
        obj->next = NULL;
        result = obj;
    }
    return result;
}

void Grid_MoveObject(GridObject *obj, Vector4 *min, Vector4 *max) {
    u32 z;
    u32 x;
    GridNode *prev;
    GridNode *newNode;
    GridNode *node;
    GridNode *next;
    GridNode *cur;
    u32 x0;
    u32 z0;
    u32 x1;
    u32 z1;

    if (obj != NULL) {
        Grid_GetCell(min, (s32 *)&x0, (s32 *)&z0);
        Grid_GetCell(max, (s32 *)&x1, (s32 *)&z1);
        if (x0 != obj->x0 || z0 != obj->z0 || x1 != obj->x1 || z1 != obj->z1) {
            for (cur = obj->nodes; cur != NULL; cur = next) {
                next = cur->objNext;
                if (cur->next != NULL) {
                    cur->next->prev = cur->prev;
                }
                if (cur->prev != NULL) {
                    cur->prev->next = cur->next;
                } else {
                    cur->cell->head = cur->next;
                }
                cur->cell->count--;
                Grid_PushFreeNode(cur);
            }
            obj->x0 = x0;
            obj->z0 = z0;
            obj->x1 = x1;
            obj->z1 = z1;
            prev = NULL;
            for (x = obj->x0; x <= obj->x1; x++) {
                for (z = obj->z0; z <= obj->z1; z++) {
                    node = ((GridManager *)gGridManager)->freeNodes;
                    newNode = NULL;
                    if (node != NULL) {
                        ((GridManager *)gGridManager)->freeNodes = node->next;
                        newNode = node;
                        *(GridResult *)node = *(GridResult *)obj;
                        node->objNext = prev;
                        node->cell = &((GridManager *)gGridManager)->cells[node->data][x * ((GridManager *)gGridManager)->numZ + z];
                        node->prev = NULL;
                        node->next = ((GridManager *)gGridManager)->cells[node->data][x * ((GridManager *)gGridManager)->numZ + z].head;
                        if (node->next != NULL) {
                            node->next->prev = node;
                        }
                        ((GridManager *)gGridManager)->cells[node->data][x * ((GridManager *)gGridManager)->numZ + z].head = node;
                        ((GridManager *)gGridManager)->cells[node->data][x * ((GridManager *)gGridManager)->numZ + z].count++;
                    }
                    prev = newNode;
                }
            }
            obj->nodes = prev;
            obj->next = NULL;
        }
    }
}

void Grid_FreeObject(u8 *object) {
    extern u8 gGridManager[];
    u8 *node;
    u8 *next;

    if (object != NULL) {
        for (node = *(u8 **)(object + 8); node != NULL; node = next) {
            next = *(u8 **)(node + 0x10);
            if (*(u8 **)(node + 8) != NULL) {
                *(u8 **)(*(u8 **)(node + 8) + 0xC) = *(u8 **)(node + 0xC);
            }
            if (*(u8 **)(node + 0xC) != NULL) {
                *(u8 **)(*(u8 **)(node + 0xC) + 8) = *(u8 **)(node + 8);
            } else {
                **(u8 ***)(node + 0x14) = *(u8 **)(node + 8);
            }
            (*(s32 *)(*(u8 **)(node + 0x14) + 4))--;
            *(u8 **)(node + 8) = ((u8 **)(gGridManager + 0x1B3B8))[0];
            ((u8 **)(gGridManager + 0x1B3B8))[0] = node;
        }
        *(u8 **)(object + 0x1C) = *(u8 **)(gGridManager + 0x233BC);
        *(u8 **)(gGridManager + 0x233BC) = object;
        *(s32 *)(gGridManager + 0x233C0) += 1;
    }
}

u32 Grid_GetObjects(Vector4 *min, Vector4 *max, u32 typeMask, GridResult *results, u32 maxResults) {
    u32 count;
    u32 x;
    u32 z;
    u32 type;
    GridNode *node;
    u32 i;
    s8 found;
    u32 x0;
    u32 z0;
    u32 x1;
    u32 z1;

    count = 0;
    Grid_GetCell(min, (s32 *)&x0, (s32 *)&z0);
    Grid_GetCell(max, (s32 *)&x1, (s32 *)&z1);
    for (x = x0; x <= x1; x++) {
        for (z = z0; z <= z1; z++) {
            for (type = 0; type < 7; type++) {
                if (typeMask & (1 << type)) {
                    node = ((GridManager *)gGridManager)->cells[type][x * ((GridManager *)gGridManager)->numZ + z].head;
                    while (node != NULL) {
                        found = 0;
                        i = 0;
                        while (i < count && !found) {
                            if (results[i].id == node->id) {
                                found = 1;
                            }
                            i++;
                        }
                        if (!found) {
                            if (count < maxResults) {
                                results[count] = *(GridResult *)node;
                                count++;
                            } else {
                                Dprintf("%d\n", count);
                                break;
                            }
                        }
                        node = node->next;
                    }
                }
            }
        }
    }
    return count;
}

#pragma push
#pragma use_lmw_stmw on
u32 Grid_GetNearestObjects(Vector4 *min, Vector4 *max, u32 typeMask, GridResult *results, u32 maxResults, s8 (*filter)(GridNode *, s32), s32 filterArg) {
    s8 first;
    u32 count;
    u32 x;
    u32 z;
    u32 type;
    GridResult *result;
    u32 i;
    s8 found;
    GridNode *node;
    u32 x0;
    u32 z0;
    u32 x1;
    u32 z1;

    first = 1;
    count = 0;
    Grid_GetCell(min, (s32 *)&x0, (s32 *)&z0);
    Grid_GetCell(max, (s32 *)&x1, (s32 *)&z1);
    while (count == 0) {
        for (x = x0; x <= x1; x++) {
            for (z = z0; z <= z1; z++) {
                if (first || x == x0 || x == x1 || z == z0 || z == z1) {
                    for (type = 0; type < 7; type++) {
                        if (typeMask & (1 << type)) {
                            node = ((GridManager *)gGridManager)->cells[type][x * ((GridManager *)gGridManager)->numZ + z].head;
                            while (node != NULL) {
                                result = results;
                                found = 0;
                                for (i = 0; i < count && !found; i++) {
                                    if (result->id == node->id) {
                                        found = 1;
                                    }
                                    result++;
                                }
                                if (!found) {
                                    if (count < maxResults) {
                                        if (filter == NULL || filter(node, filterArg) == 1) {
                                            results[count] = *(GridResult *)node;
                                            count++;
                                        }
                                    } else {
                                        node = NULL;
                                    }
                                }
                                if (node != NULL) {
                                    node = node->next;
                                }
                            }
                        }
                    }
                }
            }
        }
        if (count == 0) {
            first = 0;
            if (x0 == 0 && z0 == 0 && x1 >= ((GridManager *)gGridManager)->numX - 1 && z1 >= ((GridManager *)gGridManager)->numZ - 1) {
                break;
            }
            if (x0 != 0) {
                x0--;
            }
            if (z0 != 0) {
                z0--;
            }
            if (x1 < ((GridManager *)gGridManager)->numX - 1) {
                x1++;
            } else {
                x1 = ((GridManager *)gGridManager)->numX - 1;
            }
            if (z1 < ((GridManager *)gGridManager)->numZ - 1) {
                z1++;
            } else {
                z1 = ((GridManager *)gGridManager)->numZ - 1;
            }
        }
    }
    return count;
}

void *InterfaceManager_GetInterfaceObjects(u32 num) {
    typedef struct ObjectAllocation {
        u32 start;
        u32 count;
        s8 free;
    } ObjectAllocation;
    typedef struct InterfaceObject {
        u8 pad[0x2FC];
        u32 index;
    } InterfaceObject;
    extern ObjectAllocation g_objectAllocations[28];
    extern u32 g_numInterfaceObjectAllocations;
    extern InterfaceObject g_MasterInterfaceObjectList[500];
    extern u32 g_numInterfaceObjectsAllocated;
    void *memset(void *dst, int c, u32 n);
    InterfaceObject *obj;
    ObjectAllocation *alloc;
    u32 j;
    u32 total;
    u32 i;
    u32 idx;
    u32 n;

    for (i = 0; g_numInterfaceObjectAllocations != 0 && i < g_numInterfaceObjectAllocations - 1; i++) {
        alloc = &g_objectAllocations[i];
        if (alloc->free) {
            total = 0;
            for (j = i + 1; j < g_numInterfaceObjectAllocations &&
                            (g_objectAllocations[j].free || g_objectAllocations[j].count == 0);
                 j++) {
                total += g_objectAllocations[j].count;
                memset(&g_objectAllocations[j], 0, sizeof(ObjectAllocation));
            }
            alloc->count += total;
            i = j - 1;
        }
    }
    for (i = 0; i < g_numInterfaceObjectAllocations; i++) {
        if (g_objectAllocations[i].free && g_objectAllocations[i].count >= num) {
            if (i + 1 < g_numInterfaceObjectAllocations &&
                (g_objectAllocations[i + 1].free || g_objectAllocations[i + 1].count == 0)) {
                g_objectAllocations[i].free = 0;
                idx = g_objectAllocations[i].start;
                g_objectAllocations[i + 1].start = num + idx;
                g_MasterInterfaceObjectList[idx].index = idx;
                g_objectAllocations[i + 1].count = g_objectAllocations[i].count - num;
                g_objectAllocations[i + 1].free = 1;
                g_objectAllocations[i].count = num;
                return &g_MasterInterfaceObjectList[idx];
            }
            g_objectAllocations[i].free = 0;
            idx = g_objectAllocations[i].start;
            g_MasterInterfaceObjectList[idx].index = idx;
            return &g_MasterInterfaceObjectList[idx];
        }
    }
    if (g_numInterfaceObjectAllocations + num > 500) {
        return NULL;
    }
    if (g_numInterfaceObjectAllocations >= 28) {
        return NULL;
    }
    obj = &g_MasterInterfaceObjectList[g_numInterfaceObjectsAllocated];
    obj->index = g_numInterfaceObjectsAllocated;
    g_numInterfaceObjectsAllocated += num;
    n = g_numInterfaceObjectAllocations++;
    g_objectAllocations[n].start = obj->index;
    g_objectAllocations[n].count = num;
    g_objectAllocations[n].free = 0;
    return obj;
}

