typedef struct PathNode {
    f32 pos[3];
    u8 pad0C[0x10 - 0xC];
    u32 numLinks;
    f32 *costs;
    s32 *links;
    u8 pad1C[0x37 - 0x1C];
    u8 flags;
    struct PathNode *parent;
    struct PathNode *next;
    f32 g;
    f32 h;
    f32 f;
} PathNode;

static inline PathNode *NavHolder_PopLowestOpen(void) {
    extern PathNode *gs_pOpenListHead_803C7008;
    PathNode *head = gs_pOpenListHead_803C7008;
    PathNode *prev = NULL;
    PathNode *p;
    PathNode *best;
    f32 bestF;

    if (head == NULL) {
        return NULL;
    }
    bestF = head->f;
    p = head;
    best = head;
    for (; p->next != NULL; p = p->next) {
        if (p->next->f < bestF) {
            bestF = p->next->f;
            prev = p;
            best = p->next;
        }
    }
    if (prev == NULL) {
        gs_pOpenListHead_803C7008 = head->next;
    } else {
        prev->next = best->next;
    }
    best->flags &= ~2;
    return best;
}

s8 NavHolder_CreatePath(u8 *goal, u8 *start) {
    extern PathNode *gs_pOpenListHead_803C7008;
    extern PathNode *gs_pClosedListHead_803C7004;
    u8 *NavHolder_GetNavPoint(s32 index);
    f32 PSVECSquareDistance(f32 *a, f32 *b);
    PathNode *cur;
    PathNode *n;
    u8 i;
    PathNode *end = (PathNode *)goal;
    PathNode *node = (PathNode *)start;
    PathNode *p;
    f32 g;

    node->g = 0.0f;
    node->h = sqrt(PSVECSquareDistance(end->pos, node->pos));
    node->f = node->g + node->h;
    node->next = gs_pOpenListHead_803C7008;
    gs_pOpenListHead_803C7008 = node;
    node->flags |= 2;
    while (1) {
        cur = NavHolder_PopLowestOpen();
        if (cur == end) {
            return 1;
        }
        if (cur == NULL) {
            return 0;
        }
        for (i = 0; i < cur->numLinks; i++) {
            n = (PathNode *)NavHolder_GetNavPoint(cur->links[i]);
            if (n != end && !(s8)(n->flags & 1)) {
                if (!(s8)(n->flags & 4)) {
                    n->next = gs_pClosedListHead_803C7004;
                    gs_pClosedListHead_803C7004 = n;
                    n->flags |= 4;
                }
            } else {
                g = cur->g + cur->costs[i];
                if (!(n->flags & 6)) {
                    n->g = g;
                    n->h = sqrt(PSVECSquareDistance(end->pos, n->pos));
                    n->f = g + n->h;
                    n->parent = cur;
                    n->next = gs_pOpenListHead_803C7008;
                    gs_pOpenListHead_803C7008 = n;
                    n->flags |= 2;
                } else if (n->g > g) {
                    n->g = g;
                    n->f = g + n->h;
                    n->parent = cur;
                    if ((s8)(n->flags & 4)) {
                        p = gs_pClosedListHead_803C7004;
                        if (n == p) {
                            gs_pClosedListHead_803C7004 = p->next;
                        } else {
                            for (; p->parent != NULL; p = p->parent) {
                                if (p->parent == n) {
                                    p->parent = n->parent;
                                    break;
                                }
                            }
                        }
                        n->flags &= ~4;
                        n->next = gs_pOpenListHead_803C7008;
                        gs_pOpenListHead_803C7008 = n;
                        n->flags |= 2;
                    }
                }
            }
        }
        cur->next = gs_pClosedListHead_803C7004;
        gs_pClosedListHead_803C7004 = cur;
        cur->flags |= 4;
    }
}

u8 *NavHolder_FindPath(s32 from, s32 to) {
    extern s8 gs_useMainRouteOnly_803C7000;
    extern void *gs_pOpenListHead_803C7008;
    extern void *gs_pClosedListHead_803C7004;
    u32 RandomNumberGenerator_GetRandomInteger(u32 min, u32 max);
    s8 NavHolder_CreatePath(u8 *start, u8 *end);
    NavData *data;
    u8 *node;
    s32 offset;
    u32 i;
    u32 chance;

    if (from == -1 || to == -1) {
        return NULL;
    }
    chance = 1;
    data = gs_NavHolder_803C6CD8.data;
    if (data != NULL) {
        gs_pOpenListHead_803C7008 = NULL;
        gs_pClosedListHead_803C7004 = NULL;
        if (gs_useMainRouteOnly_803C7000) {
            chance = 100;
            gs_useMainRouteOnly_803C7000 = 0;
        }
        for (i = 0, offset = 0; i < data->numNodes; i++, offset += 0x60) {
            u32 r = RandomNumberGenerator_GetRandomInteger(chance, 100);
            node = data->nodes + offset;
            if (node[0x50] != 0 && node[0x35] >= r) {
                node[0x37] |= 1;
            } else {
                node[0x37] &= ~1;
            }
            data->nodes[offset + 0x37] &= ~6;
            *(u8 **)(data->nodes + offset + 0x38) = NULL;
        }
    }
    if (NavHolder_CreatePath(gs_NavHolder_803C6CD8.data->nodes + from * 0x60, gs_NavHolder_803C6CD8.data->nodes + to * 0x60)) {
        return gs_NavHolder_803C6CD8.data->nodes + from * 0x60;
    }
    return NULL;
}

