    v[3].color.r = 0;
    v[3].color.b = 0;
    v[3].color.g = 0;
    rect = Gfx_Add2DRectangle();
    memcpy(rect, v, sizeof(v));
    rect->blendMode = 0;
    rect->tex = 0;

    {
        f32 top = 40.0f;
        f32 left = 50.0f;

        v[0].x = v[3].x = left;
        v[0].y = v[1].y = top;
        v[2].y = v[3].y = 15.0f + top;
        v[1].x = v[2].x = left + (f32)(times[3] / 60);
    }
