    v[2].color.g = 0;
    v[2].color.b = 0;
    v[3].color.r = 0;
    v[3].color.g = 0;
    v[3].color.b = 0;
    rect = Gfx_Add2DRectangle();
    memcpy(rect, v, sizeof(v));
