void InterfaceInputAnimator_HeartBeat(void) {
    extern f32 g_fDeltaTimeMS;
    extern s32 g_LR_Direction;
    extern s32 g_UD_Direction;
    extern f32 g_LR_Counter;
    extern f32 g_UD_Counter;
    extern f32 g_LR_Max_Min;
    extern f32 g_UD_Max_Min;
    f32 dt = g_fDeltaTimeMS;

    if (g_LR_Direction == 0) {
        g_LR_Counter += dt;
        if (g_LR_Counter > g_LR_Max_Min) {
            g_LR_Counter = g_LR_Max_Min;
        }
    } else {
        g_LR_Counter -= dt;
        if (g_LR_Counter < g_LR_Max_Min) {
            g_LR_Counter = g_LR_Max_Min;
        }
    }
    if (g_UD_Direction == 0) {
        g_UD_Counter += dt;
        if (g_UD_Counter > g_UD_Max_Min) {
            g_UD_Counter = g_UD_Max_Min;
        }
    } else {
        g_UD_Counter -= dt;
        if (g_UD_Counter < g_UD_Max_Min) {
            g_UD_Counter = g_UD_Max_Min;
        }
    }
    if (g_pCallBack != NULL) {
        ((void (*)(InterfaceCallBackData *))g_pCallBack)(&g_CallBackData);
    }
}

extern char *g_moviePlaybackName;
extern u32 g_curMovieIndex;

void StateMovie_SetMovieToPlay(s32 arg0) {
    g_moviePlaybackName = (char *)arg0;
}

static inline char *StateMovie_GetNextMovieName(void) {
    static char buffer[32];
    u32 n = 0;
    u32 len;

    if (g_moviePlaybackName == NULL) {
        return NULL;
    }
    len = strlen(g_moviePlaybackName);
    if (g_curMovieIndex >= len) {
        return NULL;
    }
    {
        char *src = &g_moviePlaybackName[g_curMovieIndex];

        while (g_curMovieIndex < len) {
            if (*src != ',') {
                buffer[n++] = *src;
            } else {
                g_curMovieIndex++;
                break;
            }
            src++;
            g_curMovieIndex++;
        }
    }
    buffer[n] = '\0';
    return buffer;
}

