static inline void Thing_SetBoxContactHit(u8 *thing, Vector4 *box, Vector4 *p, Vector4 *dir, u8 *hit) {
    void XformVec(void *mtx, Vector4 *in, Vector4 *out);
    void XformVecOrientation(void *mtx, Vector4 *in, Vector4 *out);
    void PSVECSubtract(void *a, void *b, void *out);
    f32 PSVECSquareMag(void *v);
    void PSVECNormalize(void *src, void *dst);
    Vector4 q = *p;
    Vector4 normal;

    if (q.x < box[0].x) {
        q.x = box[0].x;
    }
    if (q.y < box[0].y) {
        q.y = box[0].y;
    }
    if (q.z < box[0].z) {
        q.z = box[0].z;
    }
    if (q.w < box[0].w) {
        q.w = box[0].w;
    }
    if (q.x > box[1].x) {
        q.x = box[1].x;
    }
    if (q.y > box[1].y) {
        q.y = box[1].y;
    }
    if (q.z > box[1].z) {
        q.z = box[1].z;
    }
    if (q.w > box[1].w) {
        q.w = box[1].w;
    }
    PSVECSubtract(&q, p, dir);
    normal = *dir;
    if (PSVECSquareMag(&normal) != 0.0f) {
        PSVECNormalize(&normal, &normal);
    }
    XformVec(thing + 0x10, &q, (Vector4 *)hit);
    XformVecOrientation(thing + 0x10, &normal, (Vector4 *)(hit + 0x10));
}

static inline s8 Thing_SweptSpheresTouch(u8 *a, u8 *b, f32 t) {
    s8 SegmentVsSphere(void *center, Vector4 *start, Vector4 *end, f32 radius);
    Vector4 end;
    f32 dx = ((f32 *)a)[0] - ((f32 *)b)[0];
    f32 dy = ((f32 *)a)[1] - ((f32 *)b)[1];
    f32 dz = ((f32 *)a)[2] - ((f32 *)b)[2];

    end.x = t * dx + ((Vector4 *)(a + 0x40))->x;
    end.y = t * dy + ((Vector4 *)(a + 0x40))->y;
    end.z = t * dz + ((Vector4 *)(a + 0x40))->z;
    return SegmentVsSphere(b + 0x40, (Vector4 *)(a + 0x40), &end, *(f32 *)(a + 0x70) + *(f32 *)(b + 0x70));
}

s8 Thing_TestThingCollision(u8 *a, u8 *b, f32 *t, u8 *hit) {
    typedef struct CollisionBox {
        Vector4 min;
        Vector4 max;
        Vector4 extra;
    } CollisionBox;
    typedef struct RayHit {
        Vector4 pos;
        Vector4 normal;
        u8 pad[0x30];
    } RayHit;
    void XformVec(void *mtx, Vector4 *in, Vector4 *out);
    void InverseXformVec(void *mtx, Vector4 *in, Vector4 *out);
    void XformVecOrientation(void *mtx, Vector4 *in, Vector4 *out);
    void InverseXformVecOrientation(void *mtx, Vector4 *in, Vector4 *out);
    f32 OBoxHitsOBox(void *boxA, void *a, void *boxB, void *b, u8 *hit, f32 t);
    f32 RayBoxTest(Vector4 *start, Vector4 *dir, Vector4 *box, f32 t, Vector4 *hit);
    void PSVECSubtract(void *a, void *b, void *out);
    f32 PSVECSquareMag(void *v);
    void PSVECNormalize(void *src, void *dst);
    f32 best;

    best = *t;
    switch (*(s16 *)(a + 0x80)) {
    case 3:
        best = (*(f32 (**)(void *, Vector4 *, Vector4 *, void *, f32))(*(u8 **)(b + 0x8C) + 0x38))(b, (Vector4 *)(a + 0x40), (Vector4 *)a, hit, *t);
        break;
    case 1:
        switch (*(s16 *)(b + 0x80)) {
        case 3:
            best = (*(f32 (**)(void *, Vector4 *, Vector4 *, void *, f32))(*(u8 **)(a + 0x8C) + 0x38))(a, (Vector4 *)(b + 0x40), (Vector4 *)b, hit, *t);
            break;
        case 1: {
            void *boxA;
            void *boxB;

            boxA = (*(void *(**)(void *))(*(u8 **)(a + 0x8C) + 0x40))(a);
            boxB = (*(void *(**)(void *))(*(u8 **)(b + 0x8C) + 0x40))(b);
            if (!Thing_SweptSpheresTouch(a, b, *t)) {
                return 0;
            }
            best = OBoxHitsOBox(boxA, a, boxB, b, hit, *t);
            break;
        }
        case 6: {
            RayHit rayHit;
            RayHit contact;
            CollisionBox bounds;
            Vector4 relLocal;
            Vector4 rel;
            Vector4 world;
            Vector4 local;
            Vector4 p;
            Vector4 n;
            CollisionBox *box;
            u32 *list;
            u32 i;
            f32 d;
            f32 r;

            box = (CollisionBox *)Thing_GetLocalCollision(a);
            list = (u32 *)Thing_GetLocalCollision(b);
            PSVECSubtract(b, a, &rel);
            InverseXformVecOrientation(a + 0x10, &rel, &relLocal);
            for (i = 0; i < list[0]; i++) {
                bounds = *box;
                r = ((Vector4 *)(list[1] + i * 0x20))[1].x;
                bounds.max.x += r;
                bounds.max.y += r;
                bounds.max.z += r;
                bounds.min.x -= r;
                bounds.min.y -= r;
                bounds.min.z -= r;
                XformVec(b + 0x10, (Vector4 *)(list[1] + i * 0x20), &world);
                InverseXformVec(a + 0x10, &world, &local);
                d = RayBoxTest(&local, &relLocal, &bounds.min, *t, &rayHit.pos);
                if (d < best && d > 0.0f) {
                    if (hit != NULL) {
                        p.x = d * relLocal.x + local.x;
                        p.y = d * relLocal.y + local.y;
                        p.z = d * relLocal.z + local.z;
                        contact.pos = p;
                        if (contact.pos.x < box->min.x) {
                            contact.pos.x = box->min.x;
                        }
                        if (contact.pos.y < box->min.y) {
                            contact.pos.y = box->min.y;
                        }
                        if (contact.pos.z < box->min.z) {
                            contact.pos.z = box->min.z;
                        }
                        if (contact.pos.w < box->min.w) {
                            contact.pos.w = box->min.w;
                        }
                        if (contact.pos.x > box->max.x) {
                            contact.pos.x = box->max.x;
                        }
                        if (contact.pos.y > box->max.y) {
                            contact.pos.y = box->max.y;
                        }
                        if (contact.pos.z > box->max.z) {
                            contact.pos.z = box->max.z;
                        }
                        if (contact.pos.w > box->max.w) {
                            contact.pos.w = box->max.w;
                        }
                        PSVECSubtract(&contact.pos, &p, &n);
                        contact.normal = n;
                        if (PSVECSquareMag(&contact.normal)) {
                            PSVECNormalize(&contact.normal, &contact.normal);
                        }
                        XformVec(a + 0x10, &contact.pos, (Vector4 *)hit);
                        XformVecOrientation(a + 0x10, &contact.normal, (Vector4 *)(hit + 0x10));
                    }
                    best = d;
                }
            }
            break;
        }
        }
        break;
    case 6:
        switch (*(s16 *)(b + 0x80)) {
        case 3:
            best = (*(f32 (**)(void *, Vector4 *, Vector4 *, void *, f32))(*(u8 **)(b + 0x8C) + 0x38))(a, (Vector4 *)(a + 0x40), (Vector4 *)a, hit, *t);
            break;
        case 1: {
            RayHit rayHit;
            RayHit contact;
            CollisionBox bounds;
            Vector4 relLocal;
            Vector4 rel;
            Vector4 world;
            Vector4 local;
            Vector4 p;
            Vector4 n;
            CollisionBox *box;
            u32 *list;
            u32 i;
            f32 d;
            f32 r;

            box = (CollisionBox *)Thing_GetLocalCollision(b);
            list = (u32 *)Thing_GetLocalCollision(a);
            PSVECSubtract(a, b, &rel);
            InverseXformVecOrientation(b + 0x10, &rel, &relLocal);
            for (i = 0; i < list[0]; i++) {
                bounds = *box;
                r = ((Vector4 *)(list[1] + i * 0x20))[1].x;
                bounds.max.x += r;
                bounds.max.y += r;
                bounds.max.z += r;
                bounds.min.x -= r;
                bounds.min.y -= r;
                bounds.min.z -= r;
                XformVec(a + 0x10, (Vector4 *)(list[1] + i * 0x20), &world);
                InverseXformVec(b + 0x10, &world, &local);
                d = RayBoxTest(&local, &relLocal, &bounds.min, *t, &rayHit.pos);
                if (d < best) {
                    if (hit != NULL) {
                        p.x = d * relLocal.x + local.x;
                        p.y = d * relLocal.y + local.y;
                        p.z = d * relLocal.z + local.z;
                        contact.pos = p;
                        if (contact.pos.x < box->min.x) {
                            contact.pos.x = box->min.x;
                        }
                        if (contact.pos.y < box->min.y) {
                            contact.pos.y = box->min.y;
                        }
                        if (contact.pos.z < box->min.z) {
                            contact.pos.z = box->min.z;
                        }
                        if (contact.pos.w < box->min.w) {
                            contact.pos.w = box->min.w;
                        }
                        if (contact.pos.x > box->max.x) {
                            contact.pos.x = box->max.x;
                        }
                        if (contact.pos.y > box->max.y) {
                            contact.pos.y = box->max.y;
                        }
                        if (contact.pos.z > box->max.z) {
                            contact.pos.z = box->max.z;
                        }
                        if (contact.pos.w > box->max.w) {
                            contact.pos.w = box->max.w;
                        }
                        PSVECSubtract(&contact.pos, &p, &n);
                        contact.normal = n;
                        if (PSVECSquareMag(&contact.normal)) {
                            PSVECNormalize(&contact.normal, &contact.normal);
                        }
                        XformVec(b + 0x10, &contact.pos, (Vector4 *)hit);
                        XformVecOrientation(b + 0x10, &contact.normal, (Vector4 *)(hit + 0x10));
                    }
                    best = d;
                }
            }
            break;
        }
        case 6:
            break;
        }
        break;
    }
    if (best < *t) {
        *t = best;
        return 1;
    }
    return 0;
}

