            if (pack == NULL) {
                lockedID = -1;
                break;
            }
            DataPack_EnableLoadingSounds(1);
            script = DataPack_GetScript(pack, data->packID);
            if (script == NULL) {
                break;
            }
            params.pos.x = 0.0f;
            params.pos.y = -7.0f;
            params.pos.z = 30.0f;
            params.player = data->players[0];
            params.rot.x = 0.0f;
            params.rot.y = 0.0f;
            params.rot.z = 0.0f;
            params.rot.w = 1.0f;
            params.script = script;
            params.vel.x = 0.0f;
            params.vel.y = 0.0f;
