s32 VerifyID(CARDControl *card) {
    typedef struct CARDID {
        u8 serial[32];
        u16 deviceID;
        u16 size;
        u16 encode;
        u8 padding[0x1FC - 0x26];
        u16 checkSum;
        u16 checkSumInv;
    } CARDID;
    u16 OSGetFontEncode(void);
    OSSramEx *__OSLockSramEx(void);
    s32 __OSUnlockSramEx(s32 commit);
    CARDID *id;
    u16 checksum;
    u16 checksumInv;
    OSSramEx *sramEx;
    s64 rand;
    s32 i;

    id = card->workArea;
    if (id->deviceID != 0 || id->size != card->size) {
        return -6;
    }
    __CARDCheckSum((u16 *)id, sizeof(CARDID) - sizeof(u32), &checksum, &checksumInv);
    if (id->checkSum != checksum || id->checkSumInv != checksumInv) {
        return -6;
    }
    if (id->encode != OSGetFontEncode()) {
        return -13;
    }
    rand = *(s64 *)&id->serial[12];
    sramEx = __OSLockSramEx();
    for (i = 0; i < 12; i++) {
        rand = (rand * 1103515245 + 12345) >> 16;
        if (id->serial[i] != (u8)(sramEx->flashID[card - __CARDBlock][i] + rand)) {
            __OSUnlockSramEx(0);
            return -6;
        }
        rand = ((rand * 1103515245 + 12345) >> 16) & 0x7FFF;
    }
    __OSUnlockSramEx(0);
    return 0;
}

s32 VerifyDir(CARDControl *card, s32 *outCurrent) {
    void *memcpy(void *dst, const void *src, u32 n);
    u8 *dir[2];
    CARDDirCheck *check[2];
    u16 checkSum;
    u16 checkSumInv;
    s32 i;
    s32 errors;
    s32 current;

    errors = 0;
    current = 0;
    for (i = 0; i < 2; i++) {
        dir[i] = (u8 *)card->workArea + (1 + i) * 0x2000;
        check[i] = __CARDGetDirCheck(dir[i]);
        __CARDCheckSum((u16 *)dir[i], 0x2000 - sizeof(u32), &checkSum, &checkSumInv);
        if (check[i]->checkSum != checkSum || check[i]->checkSumInv != checkSumInv) {
            card->currentDir = NULL;
            current = i;
            errors++;
        }
    }
    if (errors == 0) {
        if (card->currentDir == NULL) {
            if ((check[0]->checkCode - check[1]->checkCode) < 0) {
                current = 0;
            } else {
                current = 1;
            }
            card->currentDir = dir[current];
            memcpy(dir[current], dir[current ^ 1], 0x2000);
        } else {
            current = (card->currentDir == dir[0]) ? 0 : 1;
        }
    }
    if (outCurrent) {
        *outCurrent = current;
    }
    return errors;
}

s32 VerifyFAT(CARDControl *card, s32 *outCurrent) {
    void *memcpy(void *dst, const void *src, u32 n);
    u16 *fat[2];
    u16 *fatp;
    u16 nBlock;
    u16 cFree;
    s32 i;
    u16 checkSum;
    u16 checkSumInv;
    s32 errors;
    s32 current;

    errors = 0;
    current = 0;
    for (i = 0; i < 2; i++) {
        fatp = fat[i] = (u16 *)((u8 *)card->workArea + (3 + i) * 0x2000);
        __CARDCheckSum(&fatp[2], 0x2000 - sizeof(u32), &checkSum, &checkSumInv);
        if (fatp[0] != checkSum || fatp[1] != checkSumInv) {
            *(void **)((u8 *)card + 0x88) = NULL;
            current = i;
            errors++;
            continue;
        }
        cFree = 0;
        for (nBlock = 5; nBlock < card->cBlock; nBlock++) {
            if (fatp[nBlock] == 0) {
                cFree++;
            }
        }
        if (cFree != fatp[3]) {
            *(void **)((u8 *)card + 0x88) = NULL;
            current = i;
            errors++;
            continue;
        }
    }
    if (errors == 0) {
        if (*(void **)((u8 *)card + 0x88) == NULL) {
            if (((s16)fat[0][2] - (s16)fat[1][2]) < 0) {
                current = 0;
            } else {
                current = 1;
            }
            *(void **)((u8 *)card + 0x88) = fat[current];
            memcpy(fat[current], fat[current ^ 1], 0x2000);
        } else {
            current = (*(void **)((u8 *)card + 0x88) == fat[0]) ? 0 : 1;
        }
    }
    if (outCurrent) {
        *outCurrent = current;
    }
    return errors;
}

s32 CARDCheckExAsync(s32 chan, s32 *xferBytes, CARDCallback callback) {
    typedef struct CARDDir {
        u8 gameName[4];
        u8 company[2];
        u8 unk6[0x36 - 0x6];
        u16 startBlock;
        u16 length;
        u8 unk3A[0x40 - 0x3A];
    } CARDDir;
    s32 __CARDGetControlBlock(s32 chan, CARDControl **pcard);
    s32 VerifyID(CARDControl *card);
    s32 VerifyDir(CARDControl *card, s32 *outCurrent);
    s32 VerifyFAT(CARDControl *card, s32 *outCurrent);
    s32 __CARDUpdateDir(s32 chan, CARDCallback callback);
    s32 __CARDUpdateFatBlock(s32 chan, u16 *fat, CARDCallback callback);
    void *memcpy(void *dst, const void *src, u32 n);
    void *memset(void *dst, int c, u32 n);
    CARDControl *card;
    u8 *dir[2];
    u16 *fat[2];
    u16 *map;
    s32 result;
    s32 errors;
    s32 currentFat;
    s32 currentDir;
    s32 fileNo;
    u16 iBlock;
    u16 cBlock;
    u16 cFree;
    BOOL updateFat = FALSE;
    BOOL updateDir = FALSE;
    BOOL updateOrphan = FALSE;

    if (xferBytes) {
        *xferBytes = 0;
    }
    result = __CARDGetControlBlock(chan, &card);
    if (result < 0) {
        return result;
    }
    result = VerifyID(card);
    if (result < 0) {
        return __CARDPutControlBlock(card, result);
    }
    errors = VerifyDir(card, &currentDir);
    errors += VerifyFAT(card, &currentFat);
    if (1 < errors) {
        return __CARDPutControlBlock(card, -6);
    }
    dir[0] = (u8 *)card->workArea + (1 + 0) * 0x2000;
    dir[1] = (u8 *)card->workArea + (1 + 1) * 0x2000;
    fat[0] = (u16 *)((u8 *)card->workArea + (3 + 0) * 0x2000);
    fat[1] = (u16 *)((u8 *)card->workArea + (3 + 1) * 0x2000);
    switch (errors) {
    case 0:
        break;
    case 1:
        if (!card->currentDir) {
            card->currentDir = dir[currentDir];
            memcpy(dir[currentDir], dir[currentDir ^ 1], 0x2000);
            updateDir = TRUE;
        } else {
            card->buffer = fat[currentFat];
            memcpy(fat[currentFat], fat[currentFat ^ 1], 0x2000);
            updateFat = TRUE;
        }
        break;
    }
    map = fat[currentFat ^ 1];
    memset(map, 0, 0x2000);
    for (fileNo = 0; fileNo < 127; fileNo++) {
        CARDDir *ent = &((CARDDir *)card->currentDir)[fileNo];
        if (ent->gameName[0] == 0xFF) {
            continue;
        }
        for (iBlock = ent->startBlock, cBlock = 0; iBlock != 0xFFFF && cBlock < ent->length;
             iBlock = ((u16 *)card->buffer)[iBlock], ++cBlock) {
            if (!(iBlock >= 5 && iBlock < card->cBlock) || 1 < ++map[iBlock]) {
                return __CARDPutControlBlock(card, -6);
            }
        }
        if (cBlock != ent->length || iBlock != 0xFFFF) {
            return __CARDPutControlBlock(card, -6);
        }
    }
    cFree = 0;
    for (iBlock = 5; iBlock < card->cBlock; iBlock++) {
        u16 nextBlock = ((u16 *)card->buffer)[iBlock];
        if (map[iBlock] == 0) {
            if (nextBlock != 0) {
                ((u16 *)card->buffer)[iBlock] = 0;
                updateOrphan = TRUE;
            }
            cFree++;
        } else if (!(nextBlock >= 5 && nextBlock < card->cBlock) && nextBlock != 0xFFFF) {
            return __CARDPutControlBlock(card, -6);
        }
    }
    if (cFree != ((u16 *)card->buffer)[3]) {
        ((u16 *)card->buffer)[3] = cFree;
        updateOrphan = TRUE;
    }
    if (updateOrphan) {
        __CARDCheckSum(&((u16 *)card->buffer)[2], 0x2000 - sizeof(u32), &((u16 *)card->buffer)[0],
                       &((u16 *)card->buffer)[1]);
    }
    memcpy(fat[currentFat ^ 1], fat[currentFat], 0x2000);
    if (updateDir) {
        if (xferBytes) {
            *xferBytes = 0x2000;
        }
        return __CARDUpdateDir(chan, callback);
    }
    if (updateFat | updateOrphan) {
        if (xferBytes) {
            *xferBytes = 0x2000;
        }
        return __CARDUpdateFatBlock(chan, card->buffer, callback);
    }
    __CARDPutControlBlock(card, 0);
    if (callback) {
        BOOL enabled = OSDisableInterrupts();
        callback(chan, 0);
        OSRestoreInterrupts(enabled);
    }
    return 0;
}

static s32 DoMount(s32 chan) {
    typedef struct OSSramEx {
        u8 flashID[2][12];
        u32 wirelessKeyboardID;
        u16 wirelessPadID[4];
        u8 dvdErrorCode;
        u8 _padding0;
        u8 flashIDCheckSum[2];
    } OSSramEx;
    extern s32 SectorSizeTable_800D9860[8];
    extern s32 LatencyTable_800D9880[8];
    extern u16 __CARDVendorID;
    void __CARDExiHandler(s32 chan, void *context);
    void __CARDMountCallback(s32 chan, s32 result);
    s32 EXIGetID(s32 chan, u32 dev, u32 *id);
    s32 EXIProbe(s32 chan);
    s32 EXIUnlock(s32 chan);
    void *EXISetExiCallback(s32 chan, void *callback);
    s32 IsCard(u32 id);
    s32 __CARDClearStatus(s32 chan);
    s32 __CARDReadStatus(s32 chan, u8 *status);
    s32 __CARDUnlock(s32 chan, u8 *flashID);
    s32 __CARDEnableInterrupt(s32 chan, s32 enable);
    s32 __CARDRead(s32 chan, u32 addr, s32 length, void *dst, void *callback);
    s32 __CARDPutControlBlock(CARDControl *card, s32 result);
    OSSramEx *__OSLockSramEx(void);
    s32 __OSUnlockSramEx(s32 commit);
    void DCInvalidateRange(void *addr, u32 nBytes);
    void DoUnmount(s32 chan, s32 result);
    CARDControl *card;
    u32 id;
    u8 status;
    s32 result;
    OSSramEx *sram;
    int i;
    u8 checkSum;
    u16 vendorID;

    card = &__CARDBlock[chan];
    if (card->mountStep == 0) {
        if (EXIGetID(chan, 0, &id) == 0) {
            result = -3;
        } else if (IsCard(id)) {
            result = 0;
        } else {
            result = -2;
        }
        if (result < 0) {
            goto error;
        }
        *(u32 *)card->unk108 = id;
        card->size = id & 0xFC;
        card->sectorSize = SectorSizeTable_800D9860[(id & 0x00003800) >> 11];
        card->cBlock = (s32)((card->size * 1024 * 1024) / 8) / card->sectorSize;
        card->latency = LatencyTable_800D9880[(id & 0x00000700) >> 8];
        result = __CARDClearStatus(chan);
        if (result < 0) {
            goto error;
        }
        result = __CARDReadStatus(chan, &status);
        if (result < 0) {
            goto error;
        }
        if (!EXIProbe(chan)) {
            result = -3;
            goto error;
        }
        if (!(status & 0x40)) {
            result = __CARDUnlock(chan, card->unk18);
            if (result < 0) {
                goto error;
            }
            checkSum = 0;
            sram = __OSLockSramEx();
            for (i = 0; i < 12; i++) {
                sram->flashID[chan][i] = card->unk18[i];
                checkSum += card->unk18[i];
            }
            sram->flashIDCheckSum[chan] = ~checkSum;
            __OSUnlockSramEx(1);
            return result;
        } else {
            card->mountStep = 1;
            checkSum = 0;
            sram = __OSLockSramEx();
            for (i = 0; i < 12; i++) {
                checkSum += sram->flashID[chan][i];
            }
            __OSUnlockSramEx(0);
            if (sram->flashIDCheckSum[chan] != (u8)~checkSum) {
                result = -5;
                goto error;
            }
        }
    }
    if (card->mountStep == 1) {
        if (*(u32 *)card->unk108 == 0x80000004) {
            vendorID = *(u16 *)__OSLockSramEx()->flashID[chan];
            __OSUnlockSramEx(0);
            if (__CARDVendorID == 0xFFFF || vendorID != __CARDVendorID) {
                result = -2;
                goto error;
            }
        }
        card->mountStep = 2;
        result = __CARDEnableInterrupt(chan, 1);
        if (result < 0) {
            goto error;
        }
        EXISetExiCallback(chan, __CARDExiHandler);
        EXIUnlock(chan);
        DCInvalidateRange(card->workArea, 0xA000);
    }
    result = __CARDRead(chan, card->sectorSize * (card->mountStep - 2), 0x2000,
                        (u8 *)card->workArea + ((card->mountStep - 2) << 13), __CARDMountCallback);
    if (result < 0) {
        __CARDPutControlBlock(card, result);
    }
    return result;

error:
    EXIUnlock(chan);
    DoUnmount(chan, result);
    return result;
}

static s32 DoMount(s32 chan);
static void DoUnmount(s32 chan, s32 result);
s32 __CARDVerify(CARDControl *card);
void __CARDUnlockedHandler(s32 chan, void *context);
#pragma push
#pragma dont_inline on
void __CARDMountCallback(s32 chan, s32 result) {
    CARDControl *card;
    CARDCallback callback;

    card = &__CARDBlock[chan];
    switch (result) {
    case 0:
        if (++card->mountStep < 7) {
            result = DoMount(chan);
            if (0 <= result) {
                return;
            }
        } else {
            result = __CARDVerify(card);
        }
        break;
    case 1:
        card->unlockCallback = __CARDMountCallback;
        if (!EXILock(chan, 0, __CARDUnlockedHandler)) {
            return;
        }
        card->unlockCallback = 0;
        result = DoMount(chan);
        if (0 <= result) {
            return;
        }
        break;
    case -5:
    case -3:
        DoUnmount(chan, result);
        break;
    }
    callback = card->apiCallback;
    card->apiCallback = 0;
    __CARDPutControlBlock(card, result);
    callback(chan, result);
}

s32 CARDMountAsync(s32 chan, void *workArea, CARDCallback detachCallback, CARDCallback attachCallback) {
    s32 OSDisableInterrupts(void);
    void OSRestoreInterrupts(s32);
    void *EXISetExiCallback(s32 chan, void *exiCallback);
    void __CARDExtHandler(s32 chan, void *context);
    CARDControl *card;
    s32 enabled;

    if (chan < 0 || 2 <= chan) {
        return -128;
    }
    if (*(u8 *)0x800030E3 & 0x80) {
        return -3;
    }
    card = &__CARDBlock[chan];

    enabled = OSDisableInterrupts();
    if (card->result == -1) {
        OSRestoreInterrupts(enabled);
        return -1;
    }
    if (!card->attached && (EXIGetState(chan) & 8)) {
        OSRestoreInterrupts(enabled);
        return -2;
    }

    card->result = -1;
    card->workArea = workArea;
    card->extCallback = detachCallback;
    card->apiCallback = attachCallback ? attachCallback : (CARDCallback)__CARDDefaultApiCallback;
    card->exiCallback = 0;

    if (!card->attached && !EXIAttach(chan, __CARDExtHandler)) {
        card->result = -3;
        OSRestoreInterrupts(enabled);
        return -3;
    }

    card->mountStep = 0;
    card->attached = 1;
    EXISetExiCallback(chan, 0);
    OSCancelAlarm(&card->alarm);

    card->currentDir = 0;
    card->buffer = 0;

    OSRestoreInterrupts(enabled);

    card->unlockCallback = (CARDCallback)__CARDMountCallback;
    if (!EXILock(chan, 0, __CARDUnlockedHandler)) {
        return 0;
    }
    card->unlockCallback = 0;

    return DoMount(chan);
}

#pragma pop

s32 __CARDFreeBlock(s32 chan, u16 nBlock, CARDCallback callback) {
    s32 __CARDUpdateFatBlock(s32 chan, u16 *fat, CARDCallback callback);
    CARDControl *card;
    u16 *fat;
    u16 nextBlock;

    card = &__CARDBlock[chan];
    if (!card->attached) {
        return -3;
    }
    fat = *(u16 **)((u8 *)card + 0x88);
    while (nBlock != 0xFFFF) {
        if (nBlock < 5 || *(u16 *)((u8 *)card + 0x10) <= nBlock) {
            return -6;
        }
        nextBlock = fat[nBlock];
        fat[nBlock] = 0;
        nBlock = nextBlock;
        ++fat[3];
    }
    return __CARDUpdateFatBlock(chan, fat, callback);
}

s32 __CARDUpdateFatBlock(s32 chan, u16 *fat, void *callback) {
    void __CARDCheckSum(void *ptr, s32 length, u16 *checksum, u16 *checksumInv);
    void DCStoreRange(void *addr, u32 nBytes);
    s32 __CARDEraseSector(s32 chan, u32 addr, void *callback);
    void EraseCallback(s32 chan, s32 result);
    CARDControl *card;

    ++fat[2];
    card = &__CARDBlock[chan];
    __CARDCheckSum(fat + 2, 0x1FFC, fat, fat + 1);
    DCStoreRange(fat, 0x2000);
    *(void **)((u8 *)card + 0xD8) = callback;
    return __CARDEraseSector(chan, *(s32 *)((u8 *)card + 0xC) * ((u32)((u8 *)fat - *(u8 **)((u8 *)card + 0x80)) / 0x2000), EraseCallback);
}

void *__GXDefaultTexRegionCallback(void *obj, s32 mapID) {
    extern u8 *gx;
    s32 GXGetTexObjFmt(void *arg0);
    s32 fmt;
    u32 n;

    fmt = GXGetTexObjFmt(obj);
    if (fmt != 8 && fmt != 9 && fmt != 10) {
        n = (*(u32 *)(gx + 0x2C8))++;
        return gx + ((n & 7) * 0x10 + 0x208);
    }
    n = (*(u32 *)(gx + 0x2CC))++;
    return gx + ((n & 3) * 0x10 + 0x288);
}

