void *__GXDefaultTlutRegionCallback(u32 idx) {
    extern u8 *gx;
    void *ret;
    if (idx >= 0x14) {
        ret = 0;
    } else {
        ret = gx + (idx * 0x10 + 0x2D0);
    }
    return ret;
}

