static void DoUnmount(s32 chan, s32 result) {
    CARDControl *card;
    int enabled;

    card = &__CARDBlock[chan];
    enabled = OSDisableInterrupts();
    if (card->attached) {
        EXISetExiCallback(chan, 0);
        EXIDetach(chan);
        OSCancelAlarm(card->alarm);
        card->attached = 0;
        card->result = result;
        card->mountStep = 0;
    }
    OSRestoreInterrupts(enabled);
}

s32 CARDUnmount(s32 chan) {
    CARDControl *card;
    s32 result;

    result = __CARDGetControlBlock(chan, &card);
    if (result < 0) {
        return result;
    }
    DoUnmount(chan, -3);
    return 0;
}

void FormatCallback(s32 chan, s32 result) {
    s32 __CARDEraseSector(s32 chan, u32 addr, CARDCallback callback);
    s32 __CARDWrite(s32 chan, u32 addr, s32 length, void *dst, CARDCallback callback);
    s32 __CARDPutControlBlock(CARDControl *card, s32 result);
    CARDControl *card;
    CARDCallback callback;

    card = &__CARDBlock[chan];
    if (result < 0) {
        goto error;
    }

    ++card->formatStep;
    if (card->formatStep < 5) {
        result = __CARDEraseSector(chan, card->sectorSize * card->formatStep, FormatCallback);
        if (0 <= result) {
            return;
        }
    } else if (card->formatStep < 10) {
        s32 step = card->formatStep - 5;
        result = __CARDWrite(chan, card->sectorSize * step, 0x2000, (u8 *)card->workArea + step * 0x2000, FormatCallback);
        if (0 <= result) {
            return;
        }
    } else {
        card->currentDir = (u8 *)card->workArea + 0x2000;
        memcpy(card->currentDir, (u8 *)card->workArea + 0x4000, 0x2000);
        card->buffer = (u8 *)card->workArea + 0x6000;
        memcpy(card->buffer, (u8 *)card->workArea + 0x8000, 0x2000);
    }

error:
    callback = card->apiCallback;
    card->apiCallback = NULL;
    __CARDPutControlBlock(card, result);
    callback(chan, result);
}

s32 __CARDFormatRegionAsync(s32 chan, u16 encode, CARDCallback callback) {
    typedef struct CARDID {
        u8 serial[32];
        u16 deviceID;
        u16 size;
        u16 encode;
        u8 padding[0x1FC - 0x26];
        u16 checkSum;
        u16 checkSumInv;
    } CARDID;
    void *memset(void *dst, s32 c, u32 n);
    OSSram *__OSLockSram(void);
    s32 __OSUnlockSram(s32 commit);
    OSSramEx *__OSLockSramEx(void);
    s32 __OSUnlockSramEx(s32 commit);
    s64 OSGetTime(void);
    void __CARDCheckSum(void *ptr, s32 length, u16 *checksum, u16 *checksumInv);
    void DCStoreRange(void *addr, u32 nBytes);
    s32 __CARDEraseSector(s32 chan, u32 addr, CARDCallback callback);
    void __CARDDefaultApiCallback(void);
    CARDControl *card;
    CARDID *id;
    u8 *dir;
    CARDDirCheck *check;
    u16 *fat;
    s16 i;
    s32 result;
    OSSram *sram;
    OSSramEx *sramEx;
    u16 viDTVStatus;
    s64 time;
    s64 rand;

    result = __CARDGetControlBlock(chan, &card);
    if (result < 0) {
        return result;
    }

    id = card->workArea;
    memset(id, 0xFF, 0x2000);
    viDTVStatus = *(volatile u16 *)0xCC00206E;

    id->encode = encode;

    sram = __OSLockSram();
    *(u32 *)&id->serial[20] = sram->counterBias;
    *(u32 *)&id->serial[24] = sram->language;
    __OSUnlockSram(0);

    rand = time = OSGetTime();

    sramEx = __OSLockSramEx();
    for (i = 0; i < 12; i++) {
        rand = (rand * 1103515245 + 12345) >> 16;
        id->serial[i] = (u8)(sramEx->flashID[chan][i] + rand);
        rand = ((rand * 1103515245 + 12345) >> 16) & 0x7FFF;
    }
    __OSUnlockSramEx(0);

    *(u32 *)&id->serial[28] = viDTVStatus;
    *(s64 *)&id->serial[12] = time;

    id->deviceID = 0;
    id->size = card->size;
    __CARDCheckSum(id, sizeof(CARDID) - sizeof(u32), &id->checkSum, &id->checkSumInv);

    for (i = 0; i < 2; i++) {
        dir = (u8 *)card->workArea + (1 + i) * 0x2000;
        memset(dir, 0xFF, 0x2000);
        check = __CARDGetDirCheck(dir);
        check->checkCode = i;
        __CARDCheckSum(dir, 0x2000 - sizeof(u32), &check->checkSum, &check->checkSumInv);
    }
    for (i = 0; i < 2; i++) {
        fat = (u16 *)((u8 *)card->workArea + (3 + i) * 0x2000);
        memset(fat, 0x00, 0x2000);
        fat[2] = i;
        fat[3] = card->cBlock - 5;
        fat[4] = 4;
        __CARDCheckSum(&fat[2], 0x2000 - sizeof(u32), &fat[0], &fat[1]);
    }

    card->apiCallback = callback ? callback : (CARDCallback)__CARDDefaultApiCallback;
    DCStoreRange(card->workArea, 0xA000);

    card->formatStep = 0;
    result = __CARDEraseSector(chan, card->sectorSize * card->formatStep, FormatCallback);
    if (result < 0) {
        __CARDPutControlBlock(card, result);
    }
    return result;
}

s32 CARDFormat(s32 chan) {
    s32 result = __CARDFormatRegionAsync(chan, OSGetFontEncode(), __CARDSyncCallback);
    if (result < 0) {
        return result;
    }
    return __CARDSync(chan);
}

