    *(u8 *)(gx + 0x200) = (fmt & 0x10) == 0x10;
    peTexFmtH = (peTexFmt >> 3) & 1;
    reg = (u32 *)(gx + 0x1FC);
    *reg = (*reg & ~8) | (peTexFmtH << 3);
