    *(u32 *)(gx + 0x1EC) = (*(u32 *)(gx + 0x1EC) & ~2) | (clmpB << 1);
    *(u32 *)(gx + 0x1FC) = (*(u32 *)(gx + 0x1FC) & ~1) | clmpT;
    *(u32 *)(gx + 0x1FC) = (*(u32 *)(gx + 0x1FC) & ~2) | (clmpB << 1);
