u32 GXSetDispCopyYScale(f32 vscale) {
    extern u8 *gx;
    u32 iScale;
    u8 enable;
    u32 reg;
    u32 height;
    u32 numLines;
    u32 scale;
    u32 *cpDisp;

    iScale = (u32)(256.0f / vscale) & 0x1FF;
    enable = (iScale != 256);
    reg = iScale | 0x4E000000;
    GXWGFifo.u8 = 0x61;
    GXWGFifo.u32 = reg;
    *(u16 *)(gx + 2) = 0;
    cpDisp = (u32 *)(gx + 0x1EC);
    *cpDisp = (*cpDisp & ~0x400) | (enable << 10);
    reg = *(u32 *)(gx + 0x1E4);
    height = ((reg >> 10) & 0x3FF) + 1;
    numLines = ((((reg >> 10) & 0x3FF) << 8) / iScale) + 1;
    scale = iScale;
    if (scale > 0x80 && scale < 0x100) {
        while (!(scale & 1)) {
            scale >>= 1;
        }
        if (height % scale == 0) {
            numLines++;
        }
    }
    if (numLines > 0x400) {
        numLines = 0x400;
    }
    return numLines;
}
