        u16 vNumNot;
        u16 bpSentNot;
        u8 pad4[0x1D0 - 0x4];
        u32 cmode0;
        u32 cmode1;
        u32 zmode;
        u32 peCtrl;
        u32 cpDispSrc;
        u32 cpDispSize;
        u32 cpDispStride;
        u32 cpDisp;
