    case 1:
        alpha = gx->matColor[1] & 0xFF;
        reg = (reg & ~0xFF) | alpha;
        reg = (reg & ~0xFF00) | (mat_color.b << 8);
        reg = (reg & ~0xFF0000) | (mat_color.g << 16);
        reg = (reg & ~0xFF000000) | (mat_color.r << 24);
        colIdx = 1;
        break;
    case 2:
        reg = gx->matColor[0];
