#pragma push
#pragma scheduling off
void __GXUpdateBPMask(void) {
    typedef struct GXDataBP {
        u8 unk0[2];
        u16 bpSentNot;
        u8 unk4[0x11C];
        u32 iref;
        u32 bpMask;
        u8 unk128[0xDC];
        u32 genMode;
    } GXDataBP;
    extern GXDataBP *gx;
    u32 i;
    u32 tmap;
    u32 new_imask;

    new_imask = 0;
    for (i = 0; i < ((gx->genMode >> 16) & 7); i++) {
        switch (i) {
        case 0:
            tmap = gx->iref & 7;
            break;
        case 1:
            tmap = (gx->iref >> 6) & 7;
            break;
        case 2:
            tmap = (gx->iref >> 12) & 7;
            break;
        case 3:
            tmap = (gx->iref >> 18) & 7;
            break;
        }
        new_imask |= 1 << tmap;
    }
    if ((u8)gx->bpMask != new_imask) {
        gx->bpMask = (gx->bpMask & ~0xFF) | new_imask;
        GXWGPipe.u8 = 0x61;
        GXWGPipe.u32 = gx->bpMask;
        gx->bpSentNot = 0;
    }
}
#pragma pop

void __GXFlushTextureState(void) {
    extern u8 *const gx;
    GXWGFifo.u8 = 0x61;
    GXWGFifo.u32 = *(u32 *)(gx + 0x124);
    *(u16 *)(gx + 2) = 0;
}

void GXSetTevOp(s32 id, s32 mode) {
    void GXSetTevColorIn(s32 stage, s32 a, s32 b, s32 c, s32 d);
    void GXSetTevAlphaIn(s32 stage, s32 a, s32 b, s32 c, s32 d);
    void GXSetTevColorOp(s32 stage, s32 op, s32 bias, s32 scale, s32 clamp, s32 out_reg);
    void GXSetTevAlphaOp(s32 stage, s32 op, s32 bias, s32 scale, s32 clamp, s32 out_reg);
    s32 carg = 10;
    s32 aarg = 5;

    if (id != 0) {
        carg = 0;
        aarg = 0;
    }
    switch (mode) {
    case 0:
        GXSetTevColorIn(id, 15, 8, carg, 15);
        GXSetTevAlphaIn(id, 7, 4, aarg, 7);
        break;
    case 1:
        GXSetTevColorIn(id, carg, 8, 9, 15);
        GXSetTevAlphaIn(id, 7, 7, 7, aarg);
        break;
    case 2:
        GXSetTevColorIn(id, carg, 12, 8, 15);
        GXSetTevAlphaIn(id, 7, 4, aarg, 7);
        break;
    case 3:
        GXSetTevColorIn(id, 15, 15, 15, 8);
        GXSetTevAlphaIn(id, 7, 7, 7, 4);
        break;
    case 4:
        GXSetTevColorIn(id, 15, 15, 15, carg);
        GXSetTevAlphaIn(id, 7, 7, 7, aarg);
        break;
    }
    GXSetTevColorOp(id, 0, 0, 0, 1, 0);
    GXSetTevAlphaOp(id, 0, 0, 0, 1, 0);
}

void GXSetTevColorIn(s32 stage, s32 a, s32 b, s32 c, s32 d) {
    extern GXDataTev *const gx;
    u32 *reg = &gx->tevc[stage];
    *reg = (*reg & ~0xF000) | (a << 12);
    *reg = (*reg & ~0xF00) | (b << 8);
    *reg = (*reg & ~0xF0) | (c << 4);
    *reg = (*reg & ~0xF) | d;
    GXWGFifo.u8 = 0x61;
    GXWGFifo.u32 = *reg;
    *(u16 *)((u8 *)gx + 2) = 0;
}

void GXSetTevAlphaIn(s32 stage, s32 a, s32 b, s32 c, s32 d) {
    extern u8 *gx;
    u32 *reg;

    reg = (u32 *)(gx + (stage * 4 + 0x170));
    *reg = (*reg & ~0xE000) | (a << 13);
    *reg = (*reg & ~0x1C00) | (b << 10);
    *reg = (*reg & ~0x380) | (c << 7);
    *reg = (*reg & ~0x70) | (d << 4);
    GXWGFifo.u8 = 0x61;
    GXWGFifo.u32 = *reg;
    *(u16 *)(gx + 2) = 0;
}

void GXSetTevColorOp(s32 stage, s32 op, s32 bias, s32 scale, u8 clamp, s32 out_reg) {
    extern u8 *gx;
    u32 *reg;

    reg = (u32 *)(gx + (stage * 4 + 0x130));
    *reg = (*reg & ~0x40000) | ((op & 1) << 18);
    if (op <= 1) {
        *reg = (*reg & ~0x300000) | (scale << 20);
        *reg = (*reg & ~0x30000) | (bias << 16);
    } else {
        *reg = (*reg & ~0x300000) | (((op >> 1) & 3) << 20);
        *reg = (*reg & ~0x30000) | (3 << 16);
    }
    *reg = (*reg & ~0x80000) | (clamp << 19);
    *reg = (*reg & ~0xC00000) | (out_reg << 22);
    GXWGFifo.u8 = 0x61;
    GXWGFifo.u32 = *reg;
    *(u16 *)(gx + 2) = 0;
}

