    reg = (reg & ~0xFF) | ref0;
    reg = (reg & ~0xFF00) | (ref1 << 8);
    reg = (reg & ~0x70000) | (comp0 << 16);
    reg = (reg & ~0x380000) | (comp1 << 19);
    reg = (reg & ~0xC00000) | (op << 22);
    reg = (reg & ~0xFF000000) | (0xF3 << 24);
    GXWGFifo.u8 = 0x61;
    GXWGFifo.u32 = reg;
    *(u16 *)(gx + 2) = 0;
